// 이레 수학 · DT 카드 (irae-src/dt-map.js 에서 만든 파일이라 직접 고치지 마세요)
window.DT_COURSES = [
  {"id":"E1","part":"초등","label":"초1","items":[{"id":"E1-D01","k":"D","name":"0~9의 수","text":"수는 물건의 개수를 나타낸다. 0은 아무것도 없는 것을 나타낸다.","pre":[],"std":["2수01-01"]},{"id":"E1-D02","k":"D","name":"1 큰 수와 1 작은 수","text":"어떤 수의 바로 다음 수를 1 큰 수, 바로 앞의 수를 1 작은 수라 한다.","pre":["E1-D01"],"std":["2수01-03"]},{"id":"E1-T01","k":"T","name":"모으기와 가르기","text":"한 수는 두 수로 가를 수 있고, 가른 두 수를 모으면 다시 처음 수가 된다.","pre":["E1-D01"],"std":["2수01-04"]},{"id":"E1-D03","k":"D","name":"덧셈","text":"두 양을 합치는 것을 덧셈이라 하고 +로 쓴다. =는 양쪽이 같다는 뜻이다.","pre":["E1-T01"],"std":["2수01-05"]},{"id":"E1-D04","k":"D","name":"뺄셈","text":"덜어 내고 남은 것, 또는 두 양의 차이를 뺄셈이라 하고 −로 쓴다.","pre":["E1-T01"],"std":["2수01-05"]},{"id":"E1-T02","k":"T","name":"10 만들기","text":"더해서 10이 되는 두 수는 1과 9, 2와 8, 3과 7, 4와 6, 5와 5다.","pre":["E1-D03"],"std":["2수01-04","2수01-06"],"app":"받아올림 덧셈(8+5 = 8+2+3), 받아내림 뺄셈(14−6 = 14−4−2)"},{"id":"E1-T03","k":"T","name":"덧셈과 뺄셈의 관계","text":"3+4=7이면 7−4=3, 7−3=4다.","pre":["E1-D03","E1-D04"],"std":["2수01-07"],"app":"□가 있는 덧셈·뺄셈 식 풀기(초2, 2수01-09)"},{"id":"E1-D05","k":"D","name":"십과 몇","text":"10개씩 묶음과 낱개로 두 자리 수를 나타낸다. 35는 10이 3개, 1이 5개다.","pre":["E1-T02"],"std":["2수01-01"]},{"id":"E1-D06","k":"D","name":"두 자리 수의 자리","text":"두 자리 수에서 앞 숫자가 있는 자리를 십의 자리, 뒤 숫자가 있는 자리를 일의 자리라 한다. 십의 자리 숫자는 10이 몇 개인지를 나타낸다.","pre":["E1-D05"],"std":["2수01-02"]},{"id":"E1-T04","k":"T","name":"수의 크기 비교","text":"십의 자리 숫자가 큰 수가 더 크다. 십의 자리 숫자가 같으면 일의 자리 숫자가 큰 수가 더 크다.","pre":["E1-D06"],"std":["2수01-03"]},{"id":"E1-D07","k":"D","name":"짝수와 홀수","text":"둘씩 짝을 지었을 때 남는 것이 없으면 짝수, 하나 남으면 홀수다.","pre":["E1-D05"],"std":["2수01-01"]},{"id":"E1-D08","k":"D","name":"입체 모양","text":"상자 모양(직육면체), 둥근 기둥 모양(원기둥), 공 모양(구)이 있다.","pre":[],"std":["2수03-01"]},{"id":"E1-D09","k":"D","name":"평면 모양","text":"네모 모양, 세모 모양, 동그라미 모양이 있다.","pre":["E1-D08"],"std":["2수03-03"]},{"id":"E1-D10","k":"D","name":"비교하기","text":"길이는 길다·짧다, 무게는 무겁다·가볍다, 넓이는 넓다·좁다, 들이는 많다·적다로 비교한다.","pre":[],"std":["2수03-06"]},{"id":"E1-D11","k":"D","name":"시각 읽기","text":"짧은바늘은 시, 긴바늘은 분을 가리킨다. 긴바늘이 12면 몇 시, 6이면 몇 시 30분이다.","pre":["E1-D01"],"std":["2수03-07"]},{"id":"E1-D12","k":"D","name":"규칙","text":"모양이나 수가 일정하게 되풀이되거나 커지는 것을 규칙이라 한다.","pre":[],"std":["2수02-01","2수02-02"],"app":"규칙을 찾아 다음에 올 것 말하기, 변화 규칙과 계산식 배열의 규칙을 수나 식으로 나타내기(초4, 4수02-01, 4수02-02)"}]},
  {"id":"E2","part":"초등","label":"초2","items":[{"id":"E2-D01","k":"D","name":"세 자리 수","text":"100이 몇, 10이 몇, 1이 몇 개인지로 세 자리 수를 나타낸다. 100은 10이 10개인 수다.","pre":["E1-D06"],"std":["2수01-02"]},{"id":"E2-T01","k":"T","name":"자리값","text":"같은 숫자라도 있는 자리에 따라 나타내는 값이 다르다. 333 = 300+30+3","pre":["E2-D01"],"std":["2수01-02"]},{"id":"E2-D02","k":"D","name":"네 자리 수","text":"1000은 100이 10개인 수다. 천, 백, 십, 일의 자리로 네 자리 수를 나타낸다.","pre":["E2-T01"],"std":["2수01-02"]},{"id":"E2-T02","k":"T","name":"뛰어 세기","text":"10씩, 100씩, 1000씩 뛰어 세면 받아올림이 없는 한 십·백·천의 자리 숫자가 1씩 커진다.","pre":["E2-T01"],"std":["2수01-03"]},{"id":"E2-T03","k":"T","name":"받아올림과 받아내림","text":"한 자리에 10이 모이면 바로 윗자리의 1이 되고, 윗자리의 1은 바로 아랫자리의 10이다.","pre":["E1-T02","E2-T01"],"std":["2수01-06"],"app":"두 자리 수 덧셈·뺄셈(세로셈), 세 자리 수 덧셈·뺄셈(초3, 4수01-03)"},{"id":"E2-D03","k":"D","name":"계산 순서의 약속","text":"덧셈과 뺄셈만 있는 식은 앞에서부터 차례로 계산하기로 약속한다.","pre":["E2-T03"],"std":["2수01-08"],"app":"세 수의 계산"},{"id":"E2-D04","k":"D","name":"□가 있는 식","text":"모르는 수를 □로 나타낸 식이다. □에 알맞은 수를 넣으면 식이 맞게 된다.","pre":["E1-T03"],"std":["2수01-09"]},{"id":"E2-D05","k":"D","name":"곱셈","text":"같은 수를 여러 번 더하는 것을 곱셈으로 나타낸다. 3+3+3+3 = 3×4","pre":["E1-D03"],"std":["2수01-10"]},{"id":"E2-D06","k":"D","name":"몇의 몇 배","text":"3의 4배는 3을 4번 더한 것이고, 3×4로 쓴다.","pre":["E2-D05"],"std":["2수01-10"]},{"id":"E2-T04","k":"T","name":"곱셈구구와 1·0의 곱","text":"■단의 곱은 ■씩 커진다. 1×(어떤 수) = 그 수, 0×(어떤 수) = 0이다.","pre":["E2-D05"],"std":["2수01-11"],"app":"곱셈구구표 만들기"},{"id":"E2-T05","k":"T","name":"곱하는 순서를 바꿔도 같다","text":"3×4와 4×3은 같다.","pre":["E2-T04"],"std":["2수01-11"]},{"id":"E2-D07","k":"D","name":"삼각형·사각형·원","text":"곧은 선 3개로 둘러싸인 도형은 삼각형, 4개는 사각형이다. 어느 쪽에서 보아도 똑같이 둥근 모양은 원이다.","pre":["E1-D09"],"std":["2수03-04"]},{"id":"E2-D08","k":"D","name":"변과 꼭짓점","text":"도형을 이루는 곧은 선을 변, 두 변이 만나는 점을 꼭짓점이라 한다.","pre":["E2-D07"],"std":["2수03-05"]},{"id":"E2-D09","k":"D","name":"쌓기나무와 위치","text":"쌓기나무로 만든 모양은 위, 아래, 앞, 뒤, 오른쪽, 왼쪽으로 위치를 말한다.","pre":["E1-D08"],"std":["2수03-02"]},{"id":"E2-D10","k":"D","name":"길이의 단위","text":"자의 큰 눈금 한 칸의 길이를 1 cm라 한다. 100 cm를 1 m라 한다.","pre":["E1-D10"],"std":["2수03-10","2수03-11","2수03-12"]},{"id":"E2-T06","k":"T","name":"같은 단위끼리의 계산","text":"단위가 있는 양은 같은 단위끼리 더하고 뺀다. 100 cm가 모이면 1 m다.","pre":["E2-D10","E2-T03"],"std":["2수03-13"],"app":"길이의 덧셈·뺄셈(m·cm)"},{"id":"E2-D11","k":"D","name":"시간","text":"1시간 = 60분, 하루 = 24시간, 1주일 = 7일, 1년 = 12개월. 밤 12시부터 낮 12시까지는 오전, 그 뒤는 오후다.","pre":["E1-D11"],"std":["2수03-07","2수03-08","2수03-09"]},{"id":"E2-D12","k":"D","name":"분류와 표·그래프","text":"기준을 정해 자료를 나누는 것이 분류다. 그 수를 표와 ○ 그래프로 나타낸다.","pre":[],"std":["2수04-01","2수04-02","2수04-03"]}]},
  {"id":"E3","part":"초등","label":"초3","items":[{"id":"E3-D01","k":"D","name":"나눗셈","text":"똑같이 나누거나 같은 수만큼 덜어 내는 것을 나눗셈이라 하고 ÷로 쓴다. 12÷3=4에서 4는 몫이다.","pre":["E2-T04"],"std":["4수01-05"]},{"id":"E3-T01","k":"T","name":"곱셈과 나눗셈의 관계","text":"4×3=12이면 12÷3=4, 12÷4=3이다.","pre":["E3-D01"],"std":["4수01-05"],"app":"곱셈구구로 나눗셈의 몫 구하기"},{"id":"E3-T02","k":"T","name":"나누어 곱하기","text":"곱해지는 수(또는 곱하는 수)를 자리별로 나누어 각각 곱한 뒤 더해도 곱은 같다. 213×3 = 200×3 + 10×3 + 3×3","pre":["E2-T04","E2-T01"],"std":["4수01-04"],"app":"(세 자리 수)×(한 자리 수), (두 자리 수)×(두 자리 수) 세로셈"},{"id":"E3-D02","k":"D","name":"나머지","text":"나누어떨어지지 않을 때 남는 수를 나머지라 한다. 나머지는 나누는 수보다 작아야 한다.","pre":["E3-D01"],"std":["4수01-06"]},{"id":"E3-T03","k":"T","name":"나눗셈의 검산식","text":"(나누는 수)×(몫)+(나머지) = (나누어지는 수)","pre":["E3-D02","E3-T01"],"std":["4수01-06"],"app":"나눗셈 검산, (세 자리 수)÷(두 자리 수)(몫을 어림하고 곱해 보며 고치기, 4수01-07), 어림셈(4수01-08)"},{"id":"E3-D03","k":"D","name":"분수","text":"전체를 똑같이 나눈 것 중의 부분을 분수로 나타낸다. 아래는 분모(나눈 수), 위는 분자(부분의 수)다.","pre":["E3-D01"],"std":["4수01-09"]},{"id":"E3-D04","k":"D","name":"분수의 종류","text":"분자가 1이면 단위분수, 분자가 분모보다 작으면 진분수, 같거나 크면 가분수, 자연수와 진분수를 합친 것은 대분수다.","pre":["E3-D03"],"std":["4수01-10"]},{"id":"E3-T04","k":"T","name":"분수의 크기 비교","text":"분모가 같으면 분자가 클수록 크다. 단위분수는 분모가 작을수록 크다.","pre":["E3-D04"],"std":["4수01-11"]},{"id":"E3-D05","k":"D","name":"소수","text":"1을 10으로 똑같이 나눈 하나를 0.1이라 쓴다. 점(.)을 소수점이라 한다.","pre":["E3-D03"],"std":["4수01-12"]},{"id":"E3-T05","k":"T","name":"소수의 크기 비교","text":"자연수 부분이 큰 소수가 더 크다. 자연수 부분이 같으면 소수 첫째 자리부터 차례로 비교해 처음으로 큰 숫자가 있는 쪽이 더 크다.","pre":["E3-D05"],"std":["4수01-14"]},{"id":"E3-D06","k":"D","name":"선분·반직선·직선","text":"두 점을 곧게 이은 선은 선분, 한 점에서 시작하여 한쪽으로 끝없이 늘인 곧은 선은 반직선, 양쪽으로 끝없이 늘인 곧은 선은 직선이다.","pre":["E2-D08"],"std":["4수03-01"]},{"id":"E3-D07","k":"D","name":"각과 직각","text":"한 점에서 그은 두 반직선으로 이루어진 도형이 각이다. 종이를 반듯하게 두 번 접었을 때 생기는 각이 직각이다.","pre":["E3-D06"],"std":["4수03-02"]},{"id":"E3-D08","k":"D","name":"직각삼각형·직사각형·정사각형","text":"한 각이 직각인 삼각형은 직각삼각형, 네 각이 모두 직각인 사각형은 직사각형, 그중 네 변의 길이까지 같으면 정사각형이다.","pre":["E3-D07"],"std":["4수03-09","4수03-10"]},{"id":"E3-D09","k":"D","name":"원의 중심·반지름·지름","text":"원의 한가운데 점이 중심, 중심과 원 위의 한 점을 이은 선분이 반지름, 중심을 지나도록 원 위의 두 점을 이은 선분이 지름이다.","pre":["E2-D07"],"std":["4수03-06","4수03-07"]},{"id":"E3-T06","k":"T","name":"지름과 반지름","text":"한 원에서 반지름은 모두 같고, 지름은 반지름의 2배다.","pre":["E3-D09"],"std":["4수03-06"],"app":"컴퍼스로 원 그리기"},{"id":"E3-D10","k":"D","name":"mm와 km","text":"10 mm를 1 cm, 1000 m를 1 km라 한다.","pre":["E2-D10"],"std":["4수03-15","4수03-16"]},{"id":"E3-D11","k":"D","name":"초","text":"1분을 60으로 똑같이 나눈 하나가 1초다. 1분 = 60초","pre":["E2-D11"],"std":["4수03-13"]},{"id":"E3-D12","k":"D","name":"들이와 무게의 단위","text":"1 L = 1000 mL, 1 kg = 1000 g, 1 t = 1000 kg","pre":["E1-D10"],"std":["4수03-17 ~ 4수03-23"]},{"id":"E3-T07","k":"T","name":"단위 바꾸기","text":"같은 양은 단위를 바꾸어 나타낼 수 있다. 1시간 30분 = 90분, 1 km 200 m = 1200 m","pre":["E3-D10","E3-D11","E3-D12","E2-T06"],"std":["4수03-14","4수03-19","4수03-23"],"app":"시간·길이·들이·무게의 덧셈·뺄셈(초가 60이 되면 1분, 분이 60이 되면 1시간으로, m·mL·g이 1000이 되면 윗단위로 받아올림)"},{"id":"E3-D13","k":"D","name":"그림그래프","text":"자료의 수를 크기가 다른 그림으로 나타낸 그래프다.","pre":["E2-D12"],"std":["4수04-01"]}]},
  {"id":"E4","part":"초등","label":"초4","items":[{"id":"E4-D01","k":"D","name":"큰 수","text":"10000을 만, 만의 10000배를 억, 억의 10000배를 조라 한다. 큰 수는 뒤에서부터 네 자리씩 끊어 읽는다.","pre":["E2-D02"],"std":["4수01-01"]},{"id":"E4-T01","k":"T","name":"큰 수의 크기 비교","text":"자릿수가 많은 수가 더 크다. 자릿수가 같으면 높은 자리부터 비교해 처음으로 큰 숫자가 있는 쪽이 더 크다.","pre":["E4-D01"],"std":["4수01-02"]},{"id":"E4-D02","k":"D","name":"등호","text":"=는 양쪽의 값이 같다는 관계를 나타낸다. 3+5 = 2+6처럼 양쪽이 모두 식일 수도 있다.","pre":["E2-D04"],"std":["4수02-03"]},{"id":"E4-D03","k":"D","name":"각도","text":"직각을 90으로 똑같이 나눈 하나가 1°다. 0°보다 크고 직각보다 작은 각은 예각, 직각보다 크고 180°보다 작은 각은 둔각이다.","pre":["E3-D07"],"std":["4수03-02","4수03-24"]},{"id":"E4-T02","k":"T","name":"삼각형 세 각의 합","text":"삼각형의 세 각의 크기의 합은 180°다.","pre":["E4-D03"],"std":["4수03-25"]},{"id":"E4-T03","k":"T","name":"사각형 네 각의 합","text":"사각형의 네 각의 크기의 합은 360°다. 대각선으로 삼각형 2개로 나눌 수 있기 때문이다.","pre":["E4-T02"],"std":["4수03-25"]},{"id":"E4-D04","k":"D","name":"평면도형의 이동","text":"도형을 한 방향으로 옮기는 것을 밀기, 왼쪽·오른쪽(또는 위·아래)으로 뒤집는 것을 뒤집기, 한 점을 중심으로 돌리는 것을 돌리기라 한다.","pre":["E4-D03"],"std":["4수03-04"]},{"id":"E4-D05","k":"D","name":"위치와 방향","text":"평면에서 점의 이동은 ‘오른쪽으로 3칸, 위로 2칸’처럼 방향과 거리로 말한다.","pre":["E2-D09"],"std":["4수03-05"]},{"id":"E4-T04","k":"T","name":"분모가 같은 분수의 덧셈·뺄셈","text":"분모가 같은 분수의 합과 차는 분모는 그대로 두고 분자끼리 더하거나 뺀 것과 같다. 2/7 + 3/7 = 5/7","pre":["E3-D04"],"std":["4수01-15"],"app":"대분수의 덧셈·뺄셈"},{"id":"E4-D06","k":"D","name":"소수 두·세 자리","text":"0.1을 10으로 똑같이 나눈 하나를 0.01, 0.01을 10으로 똑같이 나눈 하나를 0.001이라 쓴다.","pre":["E3-D05"],"std":["4수01-13"]},{"id":"E4-T05","k":"T","name":"소수의 자리와 받아올림","text":"소수에서도 한 자리에 10이 모이면 바로 윗자리의 1이 된다. 0.01이 10개면 0.1, 0.1이 10개면 1이다.","pre":["E4-D06","E2-T03"],"std":["4수01-16"],"app":"소수의 덧셈·뺄셈(소수점을 맞추어 세로셈)"},{"id":"E4-D07","k":"D","name":"삼각형 분류","text":"두 변의 길이가 같으면 이등변삼각형, 세 변이 모두 같으면 정삼각형이다. 세 각이 모두 예각이면 예각삼각형, 한 각이 둔각이면 둔각삼각형이다.","pre":["E4-D03"],"std":["4수03-08","4수03-09"]},{"id":"E4-T06","k":"T","name":"이등변·정삼각형의 각","text":"이등변삼각형은 두 각의 크기가 같고, 정삼각형은 세 각이 모두 60°다.","pre":["E4-D07","E4-T02"],"std":["4수03-08"]},{"id":"E4-D08","k":"D","name":"수직과 평행","text":"두 직선이 직각으로 만나면 수직이다. 한 직선에 수직인 두 직선처럼 서로 만나지 않는 두 직선을 평행선이라 한다.","pre":["E3-D07"],"std":["4수03-03"]},{"id":"E4-D09","k":"D","name":"여러 가지 사각형","text":"평행한 변이 한 쌍이라도 있으면 사다리꼴, 두 쌍이면 평행사변형, 네 변의 길이가 모두 같으면 마름모다.","pre":["E4-D08"],"std":["4수03-10"]},{"id":"E4-T07","k":"T","name":"평행사변형의 성질","text":"평행사변형은 마주 보는 두 변의 길이가 같고, 마주 보는 두 각의 크기가 같고, 이웃한 두 각의 합은 180°다.","pre":["E4-D09","E4-T03"],"std":["4수03-10"]},{"id":"E4-D10","k":"D","name":"다각형과 대각선","text":"선분으로만 둘러싸인 도형은 다각형, 변의 길이와 각의 크기가 모두 같으면 정다각형이다. 이웃하지 않은 두 꼭짓점을 이은 선분은 대각선이다.","pre":["E4-D09"],"std":["4수03-11","4수03-12"]},{"id":"E4-D11","k":"D","name":"막대그래프·꺾은선그래프","text":"수량을 막대의 길이로 나타낸 그래프는 막대그래프, 수량을 점으로 찍고 선분으로 이은 그래프는 꺾은선그래프다.","pre":["E3-D13"],"std":["4수04-01","4수04-02","4수04-03"]}]},
  {"id":"E5","part":"초등","label":"초5","items":[{"id":"E5-D01","k":"D","name":"혼합 계산의 순서","text":"괄호 안 → 곱셈·나눗셈 → 덧셈·뺄셈 순서로 계산하고, 같은 단계끼리는 앞에서부터 하기로 약속한다.","pre":["E2-D03","E3-T01"],"std":["6수01-01"]},{"id":"E5-D02","k":"D","name":"약수와 배수","text":"어떤 수를 나누어떨어지게 하는 수는 그 수의 약수, 어떤 수를 1배, 2배, 3배 … 한 수는 그 수의 배수다.","pre":["E3-D02"],"std":["6수01-04","6수01-05"]},{"id":"E5-T01","k":"T","name":"약수와 배수의 관계","text":"12 = 3×4이면 3과 4는 12의 약수이고, 12는 3과 4의 배수다.","pre":["E5-D02"],"std":["6수01-04","6수01-05"]},{"id":"E5-D03","k":"D","name":"최대공약수·최소공배수","text":"두 수의 공통인 약수는 공약수, 그중 가장 큰 것은 최대공약수다. 공통인 배수는 공배수, 그중 가장 작은 것은 최소공배수다.","pre":["E5-T01"],"std":["6수01-04","6수01-05"]},{"id":"E5-T02","k":"T","name":"공약수·공배수와 최대공약수·최소공배수","text":"공약수는 최대공약수의 약수이고, 공배수는 최소공배수의 배수다.","pre":["E5-D03"],"std":["6수01-04","6수01-05"],"app":"공약수·공배수 모두 찾기"},{"id":"E5-D04","k":"D","name":"대응 관계","text":"한 양이 변할 때 다른 양이 일정하게 따라 변하는 관계를 □, △ 같은 기호를 써서 식으로 나타낸다. △ = □×4","pre":["E1-D12"],"std":["6수02-01"]},{"id":"E5-T03","k":"T","name":"크기가 같은 분수","text":"분모와 분자에 0이 아닌 같은 수를 곱하거나 같은 수로 나누어도 분수의 크기는 같다.","pre":["E3-D04","E5-D02"],"std":["6수01-06"],"app":"약분, 통분(공통분모는 최소공배수로)"},{"id":"E5-D05","k":"D","name":"약분과 기약분수","text":"분모와 분자를 공약수로 나누는 것이 약분이고, 분모와 분자의 공약수가 1뿐인 분수가 기약분수다.","pre":["E5-T03","E5-D03"],"std":["6수01-06"]},{"id":"E5-D06","k":"D","name":"통분","text":"분모가 다른 분수들을 크기를 바꾸지 않고 분모가 같은 분수로 만드는 것을 통분, 같아진 분모를 공통분모라 한다.","pre":["E5-T03","E5-D03"],"std":["6수01-06"]},{"id":"E5-T04","k":"T","name":"분모가 다른 분수의 크기 비교","text":"분모가 다른 두 분수는 통분하면 분자가 큰 쪽이 더 크다.","pre":["E5-D06","E3-T04"],"std":["6수01-07"]},{"id":"E5-T05","k":"T","name":"분모가 다른 분수의 덧셈·뺄셈","text":"분모가 다른 분수의 합과 차는 통분한 두 분수의 합과 차와 같다. 1/2 + 1/3 = 3/6 + 2/6 = 5/6","pre":["E5-D06","E4-T04"],"std":["6수01-08"],"app":"분모가 다른 분수의 덧셈·뺄셈(답은 기약분수로)"},{"id":"E5-D07","k":"D","name":"수의 범위","text":"이상·이하는 그 수를 포함하고, 초과·미만은 그 수를 포함하지 않는다.","pre":["E4-T01"],"std":["6수01-02"]},{"id":"E5-D08","k":"D","name":"올림·버림·반올림","text":"구하는 자리 아래 수를 올려서 나타내는 것을 올림, 버려서 나타내는 것을 버림이라 한다. 구하는 자리 바로 아래 자리의 숫자가 0~4이면 버리고 5~9이면 올리는 것을 반올림이라 한다.","pre":["E5-D07"],"std":["6수01-03"]},{"id":"E5-D09","k":"D","name":"둘레","text":"도형을 둘러싼 변의 길이의 합이다.","pre":["E4-D10"],"std":["6수03-11"]},{"id":"E5-D10","k":"D","name":"넓이의 단위","text":"한 변이 1 cm인 정사각형의 넓이를 1 cm², 한 변이 1 m인 정사각형의 넓이를 1 m², 한 변이 1 km인 정사각형의 넓이를 1 km²라 한다.","pre":["E3-D10"],"std":["6수03-12"]},{"id":"E5-T06","k":"T","name":"직사각형의 넓이","text":"직사각형의 넓이 = 가로 × 세로, 정사각형의 넓이 = 한 변 × 한 변","pre":["E5-D10"],"std":["6수03-13"]},{"id":"E5-T07","k":"T","name":"넓이 단위 사이의 관계","text":"1 m² = 10000 cm², 1 km² = 1000000 m²","pre":["E5-T06"],"std":["6수03-12"]},{"id":"E5-T08","k":"T","name":"평행사변형의 넓이","text":"평행사변형의 넓이 = 밑변 × 높이. 잘라 옮기면 직사각형이 되기 때문이다.","pre":["E5-T06","E4-T07"],"std":["6수03-14"]},{"id":"E5-T09","k":"T","name":"삼각형의 넓이","text":"삼각형의 넓이 = 밑변 × 높이 ÷ 2. 같은 삼각형 2개로 평행사변형을 만들 수 있기 때문이다.","pre":["E5-T08"],"std":["6수03-14"]},{"id":"E5-T10","k":"T","name":"사다리꼴의 넓이","text":"사다리꼴의 넓이 = (윗변 + 아랫변) × 높이 ÷ 2","pre":["E5-T09"],"std":["6수03-14"]},{"id":"E5-T11","k":"T","name":"마름모의 넓이","text":"마름모의 넓이 = 한 대각선 × 다른 대각선 ÷ 2","pre":["E5-T09"],"std":["6수03-14"]},{"id":"E5-T12","k":"T","name":"분수의 곱셈","text":"분수의 곱은 분자끼리 곱한 것을 분자로, 분모끼리 곱한 것을 분모로 하는 분수다. 2/3 × 4/5 = 8/15","pre":["E5-D05"],"std":["6수01-09"],"app":"대분수는 가분수로 바꾸어 곱하기"},{"id":"E5-T13","k":"T","name":"소수의 곱셈","text":"소수끼리의 곱은 자연수처럼 곱한 값에, 두 수의 소수 자릿수를 더한 만큼 소수점을 왼쪽으로 옮긴 것과 같다.","pre":["E4-D06","E3-T02"],"std":["6수01-13"],"app":"소수의 곱셈 세로셈"},{"id":"E5-D11","k":"D","name":"합동","text":"모양과 크기가 같아 완전히 겹치는 두 도형을 서로 합동이라 한다. 겹치는 점·변·각을 대응점·대응변·대응각이라 한다.","pre":["E4-D04"],"std":["6수03-01"]},{"id":"E5-T14","k":"T","name":"합동인 도형의 성질","text":"합동인 두 도형은 대응변의 길이와 대응각의 크기가 각각 같다.","pre":["E5-D11"],"std":["6수03-01"]},{"id":"E5-D12","k":"D","name":"선대칭·점대칭도형","text":"한 직선으로 접어 완전히 겹치면 선대칭도형, 한 점을 중심으로 180° 돌려 완전히 겹치면 점대칭도형이다.","pre":["E5-D11"],"std":["6수03-02"]},{"id":"E5-D13","k":"D","name":"직육면체와 정육면체","text":"직사각형 6개로 둘러싸인 입체는 직육면체, 정사각형 6개로 둘러싸인 입체는 정육면체다. 입체도형을 펼쳐 놓은 그림을 전개도라 한다.","pre":["E3-D08","E1-D08"],"std":["6수03-03","6수03-04"]},{"id":"E5-T15","k":"T","name":"직육면체의 구성 요소","text":"직육면체는 면 6개, 모서리 12개, 꼭짓점 8개이고, 마주 보는 두 면은 서로 평행하고 합동이다.","pre":["E5-D13"],"std":["6수03-03"],"app":"겨냥도와 전개도 그리기"},{"id":"E5-D14","k":"D","name":"평균","text":"자료 값의 합을 자료의 수로 나눈 값이다.","pre":["E3-D01"],"std":["6수04-01"]},{"id":"E5-D15","k":"D","name":"가능성","text":"일이 일어날 가능성을 ‘불가능하다~확실하다’로 말하거나 0부터 1까지의 수로 나타낸다. 반반이면 1/2이다.","pre":["E3-D03"],"std":["6수04-04","6수04-05","6수04-06"]}]},
  {"id":"E6","part":"초등","label":"초6","items":[{"id":"E6-T01","k":"T","name":"나눗셈의 몫을 분수로","text":"(자연수) ÷ (자연수)의 몫은 분수로 나타낼 수 있다. 3÷4 = 3/4","pre":["E3-D03","E3-D01"],"std":["6수01-10"]},{"id":"E6-T02","k":"T","name":"분수의 나눗셈","text":"분수로 나누는 것은 나누는 분수의 분모와 분자를 바꾼 수를 곱하는 것과 같다. 2/3 ÷ 4/5 = 2/3 × 5/4","pre":["E6-T01","E5-T12"],"std":["6수01-11"]},{"id":"E6-T03","k":"T","name":"분수와 소수의 관계","text":"분수는 (분자)÷(분모)를 계산하면 소수가 되고, 소수는 분모가 10, 100, 1000인 분수로 바꿀 수 있다.","pre":["E6-T01","E4-D06"],"std":["6수01-12"],"app":"분수와 소수의 크기 비교, (자연수)÷(자연수)의 몫을 소수로 나타내기(0을 붙여 계속 나누기, 6수01-14)"},{"id":"E6-T04","k":"T","name":"몫이 같은 나눗셈","text":"나누어지는 수와 나누는 수에 같은 수(10, 100, …)를 곱해도 몫은 같다. 1.2 ÷ 0.4 = 12 ÷ 4","pre":["E6-T01","E5-T13"],"std":["6수01-15"],"app":"소수의 나눗셈(두 수의 소수점을 같은 자리만큼 옮겨 나누기)"},{"id":"E6-D01","k":"D","name":"각기둥","text":"서로 평행하고 합동인 두 다각형을 밑면으로 하고, 옆면이 모두 직사각형인 입체도형을 각기둥이라 한다.","pre":["E5-D13","E5-D11"],"std":["6수03-05"]},{"id":"E6-D02","k":"D","name":"각뿔","text":"밑면이 다각형이고 옆면이 모두 삼각형이며 옆면이 한 점(각뿔의 꼭짓점)에서 만나는 입체다.","pre":["E6-D01"],"std":["6수03-05"]},{"id":"E6-T05","k":"T","name":"면·모서리·꼭짓점의 수","text":"n각기둥은 면 n+2, 모서리 3n, 꼭짓점 2n개다. n각뿔은 면 n+1, 모서리 2n, 꼭짓점 n+1개다.","pre":["E6-D01","E6-D02"],"std":["6수03-05"]},{"id":"E6-T06","k":"T","name":"전개도의 성질","text":"전개도를 접으면 맞닿는 두 모서리의 길이는 같다.","pre":["E5-D13"],"std":["6수03-04","6수03-06","6수03-08"],"app":"각기둥·원기둥의 전개도 그리기"},{"id":"E6-D03","k":"D","name":"원기둥·원뿔·구","text":"밑면이 평행하고 합동인 원 2개인 입체는 원기둥, 밑면이 원 1개이고 뾰족한 입체는 원뿔, 공 모양의 입체는 구다.","pre":["E6-D01","E3-D09"],"std":["6수03-07"]},{"id":"E6-D04","k":"D","name":"위·앞·옆에서 본 모양","text":"입체를 위, 앞, 옆에서 본 모양을 각각 위에서 본 모양, 앞에서 본 모양, 옆에서 본 모양이라 한다.","pre":["E2-D09"],"std":["6수03-09","6수03-10"],"app":"쌓기나무 개수 세기(층별로)"},{"id":"E6-D05","k":"D","name":"비","text":"두 수를 나눗셈으로 비교하여 a : b로 나타낸 것이다. 기호 앞의 a는 비교하는 양, 뒤의 b는 기준량이다.","pre":["E3-D01"],"std":["6수02-02"]},{"id":"E6-D06","k":"D","name":"비율과 백분율","text":"비교하는 양을 기준량으로 나눈 값을 비율이라 한다. 기준량을 100으로 할 때의 비율을 백분율이라 하고 %로 쓴다.","pre":["E6-D05","E6-T03"],"std":["6수02-03"]},{"id":"E6-T07","k":"T","name":"비의 성질","text":"비의 전항과 후항에 0이 아닌 같은 수를 곱하거나 나누어도 비율은 같다.","pre":["E6-D05","E5-T03"],"std":["6수02-04"],"app":"간단한 자연수의 비로 나타내기"},{"id":"E6-D07","k":"D","name":"비례식","text":"비율이 같은 두 비를 등호로 나타낸 식이다. 2:3 = 4:6에서 바깥의 2와 6은 외항, 안쪽의 3과 4는 내항이다.","pre":["E6-T07"],"std":["6수02-04"]},{"id":"E6-T08","k":"T","name":"비례식의 성질","text":"비례식에서 외항의 곱과 내항의 곱은 같다.","pre":["E6-D07"],"std":["6수02-04"],"app":"비례식에서 모르는 항 구하기"},{"id":"E6-D08","k":"D","name":"비례배분","text":"전체를 주어진 비로 나누는 것을 비례배분이라 한다.","pre":["E6-D05"],"std":["6수02-05"]},{"id":"E6-T09","k":"T","name":"비례배분의 식","text":"전체를 a : b로 나누면 앞의 것은 전체 × a/(a+b), 뒤의 것은 전체 × b/(a+b)이다.","pre":["E6-D08","E6-T07"],"std":["6수02-05"]},{"id":"E6-D09","k":"D","name":"원주와 원주율","text":"원의 둘레를 원주라 하고, 원주를 지름으로 나눈 값을 원주율이라 한다.","pre":["E3-T06","E6-T03"],"std":["6수03-15"]},{"id":"E6-T10","k":"T","name":"원주율은 일정하다","text":"원주율은 원의 크기와 상관없이 일정하며, 약 3.14다.","pre":["E6-D09"],"std":["6수03-15"]},{"id":"E6-T11","k":"T","name":"원주","text":"원주 = 지름 × 원주율","pre":["E6-T10"],"std":["6수03-16"]},{"id":"E6-T12","k":"T","name":"원의 넓이","text":"원의 넓이 = 반지름 × 반지름 × 원주율. 원을 잘게 잘라 붙이면 직사각형에 가까워지기 때문이다.","pre":["E6-T11","E5-T06"],"std":["6수03-16"]},{"id":"E6-T13","k":"T","name":"직육면체의 겉넓이","text":"직육면체의 겉넓이는 여섯 면의 넓이의 합이다. (가로×세로 + 세로×높이 + 가로×높이) × 2","pre":["E5-T15","E5-T06"],"std":["6수03-17"]},{"id":"E6-D10","k":"D","name":"부피의 단위","text":"한 모서리가 1 cm인 정육면체의 부피를 1 cm³, 한 모서리가 1 m인 정육면체의 부피를 1 m³라 한다.","pre":["E5-D10"],"std":["6수03-18"]},{"id":"E6-T14","k":"T","name":"직육면체의 부피","text":"직육면체의 부피 = 가로 × 세로 × 높이, 정육면체의 부피 = 한 모서리 × 한 모서리 × 한 모서리","pre":["E6-D10"],"std":["6수03-19"]},{"id":"E6-T15","k":"T","name":"부피 단위 사이의 관계","text":"1 m³ = 1000000 cm³","pre":["E6-T14"],"std":["6수03-18"]},{"id":"E6-D11","k":"D","name":"띠그래프·원그래프","text":"전체에 대한 각 부분의 비율(백분율)을 띠나 원을 나누어 나타낸 그래프다.","pre":["E6-D06","E4-D11"],"std":["6수04-02","6수04-03"]}]},
  {"id":"M1","part":"중학교","label":"중1","items":[{"id":"M1-D01","k":"D","name":"소수와 합성수","text":"1보다 큰 자연수 중 약수가 1과 자기 자신뿐인 수는 소수, 약수가 3개 이상인 수는 합성수다. 1은 소수도 합성수도 아니다.","pre":["E5-D02"],"std":["9수01-01"]},{"id":"M1-D02","k":"D","name":"거듭제곱","text":"같은 수를 여러 번 곱한 것을 거듭제곱으로 나타낸다. 2×2×2 = 2³ (밑 2, 지수 3)","pre":["E2-D05"],"std":["9수01-01"]},{"id":"M1-D03","k":"D","name":"소인수분해","text":"자연수를 소수인 약수(소인수)만의 곱으로 나타내는 것이다. 12 = 2²×3","pre":["M1-D01","M1-D02"],"std":["9수01-01"]},{"id":"M1-T01","k":"T","name":"소인수분해는 한 가지","text":"1보다 큰 자연수의 소인수분해 결과는 곱하는 순서를 빼면 한 가지뿐이다.","pre":["M1-D03"],"std":["9수01-01"]},{"id":"M1-T02","k":"T","name":"소인수분해와 최대공약수·최소공배수","text":"최대공약수는 공통인 소인수를 지수가 작은 쪽으로 골라 곱한 수이고, 최소공배수는 모든 소인수를 지수가 큰 쪽으로 골라 곱한 수다.","pre":["M1-T01","E5-D03"],"std":["9수01-02"],"app":"소인수분해로 최대공약수·최소공배수 구하기"},{"id":"M1-D04","k":"D","name":"정수","text":"양의 정수(+1, +2, …), 0, 음의 정수(−1, −2, …)를 통틀어 정수라 한다. 반대되는 두 양을 +와 −로 나타낸다.","pre":["E1-D01"],"std":["9수01-03"]},{"id":"M1-D05","k":"D","name":"유리수","text":"분자, 분모가 정수이고 분모가 0이 아닌 분수 꼴로 나타낼 수 있는 수다.","pre":["M1-D04","E3-D03"],"std":["9수01-03"]},{"id":"M1-D06","k":"D","name":"수직선과 절댓값","text":"수직선에서 원점(0)과 어떤 수를 나타내는 점 사이의 거리를 그 수의 절댓값이라 한다.","pre":["M1-D05"],"std":["9수01-04"]},{"id":"M1-T03","k":"T","name":"수의 대소","text":"양수는 0보다 크고 음수는 0보다 작다. 양수끼리는 절댓값이 클수록, 음수끼리는 절댓값이 작을수록 크다.","pre":["M1-D06"],"std":["9수01-04"]},{"id":"M1-T04","k":"T","name":"유리수의 덧셈","text":"부호가 같은 두 수의 합은 절댓값의 합에 공통인 부호를, 부호가 다른 두 수의 합은 절댓값의 차에 절댓값이 큰 수의 부호를 붙인 것이다.","pre":["M1-D06"],"std":["9수01-05"]},{"id":"M1-T05","k":"T","name":"유리수의 뺄셈","text":"어떤 수를 빼는 것은 그 수의 부호를 바꾸어 더하는 것과 같다. a − b = a + (−b)","pre":["M1-T04"],"std":["9수01-05"]},{"id":"M1-T06","k":"T","name":"곱셈·나눗셈의 부호","text":"0이 아닌 두 수의 곱과 몫은 절댓값끼리 곱하거나 나눈 값에, 음수의 개수가 짝수면 +, 홀수면 −를 붙인 것이다. 어떤 수에 0을 곱하면 0이다.","pre":["M1-D06"],"std":["9수01-05"]},{"id":"M1-D07","k":"D","name":"역수","text":"두 수의 곱이 1일 때 한 수를 다른 수의 역수라 한다.","pre":["E6-T02"],"std":["9수01-05"]},{"id":"M1-T07","k":"T","name":"나눗셈과 역수","text":"어떤 수로 나누는 것은 그 수의 역수를 곱하는 것과 같다. a ÷ b = a × (1/b) (b ≠ 0)","pre":["M1-D07"],"std":["9수01-05"],"app":"유리수의 나눗셈"},{"id":"M1-T08","k":"T","name":"계산 법칙","text":"덧셈과 곱셈에서 교환법칙과 결합법칙이 성립하고, a×(b+c) = a×b + a×c (분배법칙)이다.","pre":["M1-T04","M1-T06"],"std":["9수01-05"],"app":"(단항식)×(다항식), (다항식)÷(단항식)(중2, 9수02-10)"},{"id":"M1-D08","k":"D","name":"문자와 식의 값","text":"수 대신 문자를 써서 식을 나타낸다. 곱셈 기호는 생략하고 수를 문자 앞에 쓴다. 문자에 수를 대입해 얻은 값이 식의 값이다.","pre":["E2-D04","M1-T08"],"std":["9수02-01"]},{"id":"M1-D09","k":"D","name":"항·계수·차수·동류항","text":"수나 문자의 곱으로만 이루어진 식을 항이라 한다. 문자 앞의 수는 계수, 문자가 곱해진 개수는 차수, 문자와 차수가 같은 항은 동류항이다. 하나 또는 둘 이상의 항의 합으로 이루어진 식을 다항식, 항이 하나뿐인 다항식을 단항식, 수만으로 이루어진 항을 상수항이라 한다. 차수가 1인 다항식이 일차식이다.","pre":["M1-D08"],"std":["9수02-02"]},{"id":"M1-T09","k":"T","name":"동류항의 계산","text":"동류항끼리는 계수끼리 더하거나 빼서 하나의 항으로 정리할 수 있다. 2x + 3x = (2+3)x = 5x","pre":["M1-D09","M1-T08"],"std":["9수02-02"],"app":"일차식의 덧셈·뺄셈, 다항식(이차식)의 덧셈·뺄셈(중2, 9수02-09)"},{"id":"M1-D10","k":"D","name":"방정식과 해","text":"문자의 값에 따라 참·거짓이 달라지는 등식을 방정식, 참이 되게 하는 값을 해라 한다. 문자에 어떤 값을 넣어도 참인 등식은 항등식이다.","pre":["M1-D08","E4-D02"],"std":["9수02-03"]},{"id":"M1-T10","k":"T","name":"등식의 성질","text":"등식의 양변에 같은 수를 더하거나, 빼거나, 곱하거나, 0이 아닌 같은 수로 나누어도 등식은 성립한다.","pre":["M1-D10"],"std":["9수02-03"],"app":"일차방정식의 풀이(이항하여 ax = b 꼴로 만든 뒤 양변을 a로 나누기)"},{"id":"M1-D11","k":"D","name":"이항","text":"등식의 한 변에 있는 항을 부호를 바꾸어 다른 변으로 옮기는 것을 이항이라 한다.","pre":["M1-T10"],"std":["9수02-04"]},{"id":"M1-D12","k":"D","name":"순서쌍과 좌표","text":"두 수의 순서를 정해 쌍으로 나타낸 것이 순서쌍이다. 좌표평면 위의 점 P는 (x좌표, y좌표)로 나타내고, 두 축으로 나눠진 네 부분을 사분면이라 한다.","pre":["M1-D06","E4-D05"],"std":["9수02-05"]},{"id":"M1-D13","k":"D","name":"그래프","text":"두 양 사이의 관계를 좌표평면 위의 점, 선, 곡선으로 나타낸 것이다.","pre":["M1-D12"],"std":["9수02-06"]},{"id":"M1-D14","k":"D","name":"정비례","text":"x가 2배, 3배…가 될 때 y도 2배, 3배…가 되는 관계다. y = ax (a ≠ 0)","pre":["E5-D04","M1-D13"],"std":["9수02-07"]},{"id":"M1-T11","k":"T","name":"정비례의 그래프","text":"y = ax의 그래프는 원점을 지나는 직선이다. a > 0이면 오른쪽 위로, a < 0이면 오른쪽 아래로 향한다.","pre":["M1-D14"],"std":["9수02-07"]},{"id":"M1-D15","k":"D","name":"반비례","text":"x가 2배, 3배…가 될 때 y는 1/2배, 1/3배…가 되는 관계다. y = a/x (a ≠ 0)","pre":["M1-D14"],"std":["9수02-07"]},{"id":"M1-T12","k":"T","name":"반비례의 그래프","text":"y = a/x의 그래프는 좌표축에 한없이 가까워지는 한 쌍의 매끄러운 곡선이다.","pre":["M1-D15"],"std":["9수02-07"]},{"id":"M1-D16","k":"D","name":"점·선·면과 중점","text":"선과 선(또는 선과 면)이 만나는 점이 교점, 면과 면이 만나는 선이 교선이다. 선분을 이등분하는 점이 중점이다.","pre":["E3-D06"],"std":["9수03-01"]},{"id":"M1-D17","k":"D","name":"맞꼭지각","text":"두 직선이 만날 때 생기는 네 각 중 서로 마주 보는 두 각이다.","pre":["E4-D03"],"std":["9수03-01"]},{"id":"M1-T13","k":"T","name":"맞꼭지각의 성질","text":"맞꼭지각의 크기는 서로 같다.","pre":["M1-D17"],"std":["9수03-01"]},{"id":"M1-D18","k":"D","name":"수선과 거리","text":"점 P에서 직선 l에 내린 수선의 발을 H라 할 때, 선분 PH의 길이가 점과 직선 사이의 거리다.","pre":["E4-D08"],"std":["9수03-01"]},{"id":"M1-D19","k":"D","name":"평행과 꼬인 위치","text":"한 평면 위에서 만나지 않는 두 직선은 평행하다고 한다. 공간에서 만나지도 평행하지도 않은 두 직선은 꼬인 위치에 있다고 한다.","pre":["M1-D16"],"std":["9수03-01"]},{"id":"M1-T14","k":"T","name":"두 직선의 위치 관계","text":"평면에서 두 직선은 한 점에서 만나거나, 평행하거나, 일치한다. 공간에서는 여기에 꼬인 위치가 더해진다.","pre":["M1-D19"],"std":["9수03-01"]},{"id":"M1-D20","k":"D","name":"동위각과 엇각","text":"두 직선이 다른 한 직선과 만날 때, 같은 위치에 있는 각을 동위각, 엇갈린 위치에 있는 각을 엇각이라 한다.","pre":["M1-D17"],"std":["9수03-02"]},{"id":"M1-T15","k":"T","name":"평행선의 성질","text":"두 직선이 평행하면 동위각과 엇각의 크기가 각각 같다. 거꾸로 동위각이나 엇각이 같으면 두 직선은 평행하다.","pre":["M1-D20"],"std":["9수03-02"]},{"id":"M1-D21","k":"D","name":"작도","text":"눈금 없는 자와 컴퍼스만 사용하여 도형을 그리는 것이다.","pre":["E3-D09"],"std":["9수03-03"]},{"id":"M1-T16","k":"T","name":"삼각형이 하나로 정해지는 조건","text":"세 변의 길이, 두 변의 길이와 그 끼인각, 한 변의 길이와 양 끝 각이 주어지면 삼각형이 하나로 정해진다. 가장 긴 변은 나머지 두 변의 길이의 합보다 작아야 한다.","pre":["M1-D21"],"std":["9수03-03"],"app":"삼각형의 작도"},{"id":"M1-T17","k":"T","name":"삼각형의 합동 조건","text":"세 변의 길이가 각각 같거나(SSS), 두 변의 길이와 그 끼인각이 같거나(SAS), 한 변의 길이와 양 끝 각이 같으면(ASA) 두 삼각형은 합동이다.","pre":["M1-T16","E5-T14"],"std":["9수03-04"]},{"id":"M1-T18","k":"T","name":"삼각형의 외각","text":"삼각형의 한 외각의 크기는 그와 이웃하지 않는 두 내각의 크기의 합과 같다.","pre":["E4-T02"],"std":["9수03-05"]},{"id":"M1-T19","k":"T","name":"다각형의 각과 대각선","text":"n각형의 내각의 크기의 합은 180°×(n−2), 외각의 크기의 합은 항상 360°, 대각선의 개수는 n(n−3)/2이다.","pre":["M1-T18","E4-D10"],"std":["9수03-05"]},{"id":"M1-D22","k":"D","name":"부채꼴과 호·현","text":"원 위의 두 점 사이의 원의 일부는 호, 두 점을 잇는 선분은 현이다. 두 반지름과 호로 둘러싸인 도형이 부채꼴이고, 두 반지름이 이루는 각이 중심각이다. 원주율은 π로 쓴다.","pre":["E3-D09","E6-D09"],"std":["9수03-06"]},{"id":"M1-T20","k":"T","name":"중심각과 호","text":"한 원에서 부채꼴의 호의 길이와 넓이는 각각 중심각의 크기에 정비례한다. 현의 길이는 정비례하지 않는다.","pre":["M1-D22","M1-D14"],"std":["9수03-06"]},{"id":"M1-T21","k":"T","name":"부채꼴의 호의 길이와 넓이","text":"반지름 r, 중심각 x°일 때 호의 길이 l = 2πr × x/360, 넓이 S = πr² × x/360 = (1/2)rl","pre":["M1-T20","E6-T12"],"std":["9수03-06"]},{"id":"M1-D23","k":"D","name":"다면체와 정다면체","text":"다각형인 면으로만 둘러싸인 입체가 다면체다. 모든 면이 합동인 정다각형이고 각 꼭짓점에 모인 면의 개수가 같은 다면체가 정다면체다.","pre":["E6-D01","E6-D02"],"std":["9수03-07"]},{"id":"M1-T22","k":"T","name":"정다면체는 다섯 가지","text":"정다면체는 정사면체, 정육면체, 정팔면체, 정십이면체, 정이십면체의 다섯 가지뿐이다.","pre":["M1-D23","M1-T19"],"std":["9수03-07"]},{"id":"M1-D24","k":"D","name":"회전체","text":"평면도형을 한 직선(회전축)을 축으로 한 바퀴 돌려 생기는 입체다.","pre":["E6-D03"],"std":["9수03-07"]},{"id":"M1-T23","k":"T","name":"회전체의 단면","text":"회전체를 회전축에 수직인 평면으로 자르면 단면은 원이고, 회전축을 포함하는 평면으로 자르면 단면은 회전축에 대하여 선대칭도형이다.","pre":["M1-D24","E5-D12"],"std":["9수03-07"]},{"id":"M1-T24","k":"T","name":"기둥과 뿔의 겉넓이와 부피","text":"기둥의 부피 = 밑넓이 × 높이, 뿔의 부피 = (1/3) × 밑넓이 × 높이. 겉넓이는 전개도의 넓이와 같다.","pre":["E6-T14","E6-T06"],"std":["9수03-08"]},{"id":"M1-T25","k":"T","name":"구의 겉넓이와 부피","text":"반지름이 r인 구의 겉넓이는 4πr², 부피는 (4/3)πr³이다.","pre":["M1-T24"],"std":["9수03-08"]},{"id":"M1-D25","k":"D","name":"대푯값","text":"자료 전체를 대표하는 값이다. 평균 외에 크기 순으로 늘어놓았을 때 한가운데 값인 중앙값, 가장 많이 나타난 값인 최빈값이 있다.","pre":["E5-D14"],"std":["9수04-01"]},{"id":"M1-D26","k":"D","name":"줄기와 잎 그림·도수분포표","text":"자료를 줄기와 잎으로 나누어 나타낸 그림이 줄기와 잎 그림이다. 구간(계급)을 나누고 각 계급의 자료 수(도수)를 나타낸 표가 도수분포표다.","pre":["E4-D11"],"std":["9수04-02"]},{"id":"M1-D27","k":"D","name":"히스토그램·도수분포다각형","text":"도수분포표를 계급의 크기를 가로, 도수를 세로로 하는 직사각형으로 나타낸 것이 히스토그램, 각 직사각형 윗변의 중앙의 점을 차례로 선분으로 잇고, 양 끝에 도수가 0인 계급을 하나씩 더 생각하여 그 중앙의 점까지 이은 꺾은선이 도수분포다각형이다.","pre":["M1-D26"],"std":["9수04-02"]},{"id":"M1-D28","k":"D","name":"상대도수","text":"(그 계급의 도수) ÷ (도수의 총합)을 그 계급의 상대도수라 한다.","pre":["M1-D26","E6-D06"],"std":["9수04-03","9수04-04"],"app":"총합이 다른 두 집단 비교하기"}]},
  {"id":"M2","part":"중학교","label":"중2","items":[{"id":"M2-D01","k":"D","name":"유한소수와 순환소수","text":"소수점 아래 0이 아닌 숫자가 유한 개인 소수는 유한소수, 일정한 숫자의 배열(순환마디)이 끝없이 되풀이되는 소수는 순환소수다.","pre":["E6-T03","M1-D05"],"std":["9수01-06"]},{"id":"M2-T01","k":"T","name":"유한소수가 되는 조건","text":"기약분수의 분모를 소인수분해했을 때 소인수가 2나 5뿐이면 유한소수로, 그 외의 소인수가 있으면 순환소수로 나타낼 수 있다.","pre":["M2-D01","M1-D03"],"std":["9수01-06"]},{"id":"M2-T02","k":"T","name":"순환소수는 유리수","text":"모든 순환소수는 분수로 나타낼 수 있다. 0.333… = 1/3","pre":["M2-D01"],"std":["9수01-06"],"app":"순환소수를 분수로 고치기"},{"id":"M2-T03","k":"T","name":"지수법칙","text":"aᵐ × aⁿ = aᵐ⁺ⁿ, (aᵐ)ⁿ = aᵐⁿ, (ab)ⁿ = aⁿbⁿ. aᵐ ÷ aⁿ (a ≠ 0)은 m > n이면 aᵐ⁻ⁿ, m = n이면 1, m < n이면 1/aⁿ⁻ᵐ이다.","pre":["M1-D02"],"std":["9수02-08"],"app":"단항식의 곱셈·나눗셈"},{"id":"M2-D02","k":"D","name":"부등식과 해","text":"부등호(<, >, ≤, ≥)로 두 수나 식의 대소 관계를 나타낸 식이다. 부등식을 참이 되게 하는 미지수의 값이 해다.","pre":["M1-D10","E5-D07"],"std":["9수02-11"]},{"id":"M2-T04","k":"T","name":"부등식의 성질","text":"양변에 같은 수를 더하거나 빼도, 양수를 곱하거나 나누어도 부등호 방향은 그대로다. 음수를 곱하거나 나누면 부등호 방향이 바뀐다.","pre":["M2-D02","M1-T10"],"std":["9수02-11"],"app":"일차부등식의 풀이, 해를 수직선에 나타내기"},{"id":"M2-D03","k":"D","name":"일차부등식","text":"이항하여 정리했을 때 (일차식) > 0, (일차식) < 0, (일차식) ≥ 0, (일차식) ≤ 0 중 하나의 꼴이 되는 부등식이다.","pre":["M2-T04","M1-D11"],"std":["9수02-12"]},{"id":"M2-D04","k":"D","name":"연립일차방정식","text":"미지수가 2개인 일차방정식 두 개를 한 쌍으로 묶은 것이다. 두 방정식을 동시에 만족하는 x, y의 값이 해다.","pre":["M1-D10"],"std":["9수02-13"]},{"id":"M2-T05","k":"T","name":"해를 바꾸지 않는 변형","text":"연립방정식에서 한 방정식의 양변에 0이 아닌 같은 수를 곱하거나, 두 방정식을 변끼리 더하거나 빼거나, 한 문자에 그것과 같은 식을 대입해도 해는 바뀌지 않는다.","pre":["M2-D04","M1-T10"],"std":["9수02-13"],"app":"가감법, 대입법, 연립이차방정식의 풀이(고1, 10공수1-02-08)"},{"id":"M2-D05","k":"D","name":"함수","text":"x의 값이 하나 정해지면 y의 값이 오직 하나씩 정해질 때 y를 x의 함수라 하고 y = f(x)로 나타낸다. f(a)는 x = a일 때의 함숫값이다.","pre":["M1-D14","M1-D15"],"std":["9수02-14"]},{"id":"M2-D06","k":"D","name":"일차함수","text":"y = ax + b (a ≠ 0)처럼 y가 x에 대한 일차식으로 나타나는 함수다.","pre":["M2-D05"],"std":["9수02-15"]},{"id":"M2-T06","k":"T","name":"일차함수의 그래프","text":"y = ax + b의 그래프는 y = ax의 그래프를 y축의 방향으로 b만큼 평행이동한 직선이다.","pre":["M2-D06","M1-T11"],"std":["9수02-15"]},{"id":"M2-D07","k":"D","name":"x절편과 y절편","text":"그래프가 x축과 만나는 점의 x좌표가 x절편, y축과 만나는 점의 y좌표가 y절편이다.","pre":["M2-T06"],"std":["9수02-16"]},{"id":"M2-D08","k":"D","name":"기울기","text":"직선 위의 두 점에 대하여 (y의 값의 증가량) ÷ (x의 값의 증가량)을 기울기라 한다.","pre":["M2-T06"],"std":["9수02-16"]},{"id":"M2-T07","k":"T","name":"일차함수의 기울기","text":"일차함수 y = ax + b의 그래프의 기울기는 어느 두 점을 잡아도 항상 a다.","pre":["M2-D08"],"std":["9수02-16"]},{"id":"M2-T08","k":"T","name":"직선은 두 조건으로 정해진다","text":"0이 아닌 기울기와 한 점, 또는 x좌표도 y좌표도 서로 다른 두 점이 주어지면 일차함수의 식은 하나로 정해진다.","pre":["M2-D07","M2-T07"],"std":["9수02-16"],"app":"일차함수의 식 구하기"},{"id":"M2-T09","k":"T","name":"일차방정식의 그래프","text":"a, b가 동시에 0은 아닐 때 일차방정식 ax + by + c = 0의 그래프는 직선이다. a ≠ 0, b ≠ 0이면 일차함수 y = −(a/b)x − c/b의 그래프와 같고, a = 0이면 x축에, b = 0이면 y축에 평행한 직선이다.","pre":["M2-T06"],"std":["9수02-17"]},{"id":"M2-T10","k":"T","name":"연립방정식과 두 직선","text":"연립방정식의 해는 두 직선의 교점의 좌표다. 두 직선이 평행하면 해가 없고, 일치하면 해가 무수히 많다.","pre":["M2-T09","M2-D04"],"std":["9수02-18"]},{"id":"M2-D09","k":"D","name":"이등변삼각형","text":"두 변의 길이가 같은 삼각형이다. 길이가 같은 두 변이 이루는 각이 꼭지각, 나머지 한 변이 밑변, 밑변의 양 끝 각이 밑각이다.","pre":["E4-D07"],"std":["9수03-09"]},{"id":"M2-T11","k":"T","name":"이등변삼각형의 성질","text":"두 밑각의 크기는 같고, 꼭지각의 이등분선은 밑변을 수직이등분한다. 거꾸로 두 각의 크기가 같은 삼각형은 이등변삼각형이다.","pre":["M2-D09","M1-T17"],"std":["9수03-09"]},{"id":"M2-T12","k":"T","name":"직각삼각형의 합동 조건","text":"빗변의 길이와 한 예각의 크기가 같거나(RHA), 빗변의 길이와 다른 한 변의 길이가 같으면(RHS) 두 직각삼각형은 합동이다.","pre":["M1-T17"],"std":["9수03-09","9수03-10"]},{"id":"M2-D10","k":"D","name":"외심과 내심","text":"삼각형의 세 꼭짓점을 지나는 원(외접원)의 중심이 외심, 세 변에 접하는 원(내접원)의 중심이 내심이다. 원과 직선이 한 점에서만 만날 때 직선이 원에 접한다고 한다.","pre":["M2-T12"],"std":["9수03-10"]},{"id":"M2-T13","k":"T","name":"외심의 성질","text":"외심은 세 변의 수직이등분선의 교점이고, 세 꼭짓점까지의 거리가 같다. 직각삼각형의 외심은 빗변의 중점이다.","pre":["M2-D10"],"std":["9수03-10"]},{"id":"M2-T14","k":"T","name":"내심의 성질","text":"내심은 세 내각의 이등분선의 교점이고, 세 변까지의 거리가 같다.","pre":["M2-D10"],"std":["9수03-10"]},{"id":"M2-T15","k":"T","name":"평행사변형의 성질","text":"두 쌍의 대변의 길이가 각각 같고, 두 쌍의 대각의 크기가 각각 같고, 두 대각선은 서로 다른 것을 이등분한다.","pre":["E4-T07","M1-T17"],"std":["9수03-11"]},{"id":"M2-T16","k":"T","name":"평행사변형이 되는 조건","text":"두 쌍의 대변이 각각 평행하거나, 두 쌍의 대변의 길이가 각각 같거나, 두 쌍의 대각의 크기가 각각 같거나, 두 대각선이 서로 다른 것을 이등분하거나, 한 쌍의 대변이 평행하고 그 길이가 같으면 평행사변형이다.","pre":["M2-T15"],"std":["9수03-11"]},{"id":"M2-T17","k":"T","name":"여러 사각형의 대각선","text":"직사각형은 두 대각선의 길이가 같고, 마름모는 두 대각선이 서로 수직이등분하며, 정사각형은 두 성질을 모두 갖는다.","pre":["M2-T15"],"std":["9수03-11"]},{"id":"M2-D11","k":"D","name":"닮음","text":"한 도형을 일정한 비율로 확대하거나 축소한 것이 다른 도형과 합동일 때 두 도형은 닮았다고 한다. 대응변의 길이의 비가 닮음비다.","pre":["E5-D11","E6-D05"],"std":["9수03-12"]},{"id":"M2-T18","k":"T","name":"닮은 도형의 성질","text":"닮은 도형에서 대응변의 길이의 비는 일정하고 대응각의 크기는 같다. 닮음비가 m : n이면 넓이의 비는 m² : n², 부피의 비는 m³ : n³이다.","pre":["M2-D11"],"std":["9수03-12"]},{"id":"M2-T19","k":"T","name":"삼각형의 닮음 조건","text":"세 쌍의 대응변의 길이의 비가 같거나(SSS), 두 쌍의 대응변의 길이의 비가 같고 그 끼인각이 같거나(SAS), 두 쌍의 대응각이 같으면(AA) 두 삼각형은 닮은 도형이다.","pre":["M2-T18","M1-T17"],"std":["9수03-13"]},{"id":"M2-T20","k":"T","name":"삼각형과 평행선","text":"삼각형의 한 변에 평행한 직선이 다른 두 변과 만나면, 그 두 변은 같은 비로 나뉜다. 세 개 이상의 평행선이 다른 두 직선과 만나서 생기는 선분의 길이의 비도 같다.","pre":["M2-T19","M1-T15"],"std":["9수03-14"]},{"id":"M2-T21","k":"T","name":"삼각형의 두 변의 중점","text":"삼각형의 두 변의 중점을 잇는 선분은 나머지 한 변과 평행하고, 그 길이는 나머지 한 변의 1/2이다.","pre":["M2-T20"],"std":["9수03-14"]},{"id":"M2-T22","k":"T","name":"피타고라스 정리","text":"직각삼각형에서 두 변의 길이를 a, b, 빗변의 길이를 c라 하면 a² + b² = c²이다.","pre":["E5-T09","M1-D02"],"std":["9수03-15"]},{"id":"M2-T23","k":"T","name":"피타고라스 정리의 역","text":"세 변의 길이가 a, b, c인 삼각형에서 a² + b² = c²이면 이 삼각형은 빗변의 길이가 c인 직각삼각형이다.","pre":["M2-T22"],"std":["9수03-15"]},{"id":"M2-D12","k":"D","name":"사건과 경우의 수","text":"어떤 실험이나 관찰에서 일어날 수 있는 결과를 사건이라 하고, 사건이 일어날 수 있는 가짓수를 경우의 수라 한다.","pre":["E5-D15"],"std":["9수04-05"]},{"id":"M2-T24","k":"T","name":"경우의 수의 합과 곱","text":"두 사건이 동시에 일어나지 않으면 경우의 수를 더하고(m + n), A가 일어나는 각 경우마다 B가 일어나는 경우가 n가지씩이면 곱한다(m × n).","pre":["M2-D12"],"std":["9수04-05"]},{"id":"M2-D13","k":"D","name":"확률","text":"각 경우가 일어날 가능성이 같을 때, 사건 A가 일어날 확률은 (A가 일어나는 경우의 수) ÷ (모든 경우의 수)다.","pre":["M2-T24","E5-D15"],"std":["9수04-06"]},{"id":"M2-T25","k":"T","name":"확률의 기본 성질","text":"확률 p는 0 ≤ p ≤ 1이다. 반드시 일어나는 사건의 확률은 1, 절대 일어나지 않는 사건의 확률은 0이다.","pre":["M2-D13"],"std":["9수04-06"]},{"id":"M2-T26","k":"T","name":"일어나지 않을 확률","text":"사건 A가 일어날 확률이 p이면, A가 일어나지 않을 확률은 1 − p다.","pre":["M2-T25"],"std":["9수04-06"]}]},
  {"id":"M3","part":"중학교","label":"중3","items":[{"id":"M3-D01","k":"D","name":"제곱근","text":"어떤 수 x를 제곱하여 a가 될 때 x를 a의 제곱근이라 한다. 양수 a의 제곱근 중 양수인 것을 √a, 음수인 것을 −√a로 쓴다.","pre":["M1-D02","M1-T06"],"std":["9수01-07"]},{"id":"M3-T01","k":"T","name":"제곱근의 개수","text":"양수의 제곱근은 절댓값이 같고 부호가 반대인 두 개(±√a)이고, 0의 제곱근은 0뿐이며, 음수의 제곱근은 (실수 범위에서) 없다.","pre":["M3-D01","M1-T06"],"std":["9수01-07"]},{"id":"M3-T02","k":"T","name":"제곱근의 성질","text":"a > 0일 때 (√a)² = a, (−√a)² = a이다. √(a²)는 a의 절댓값이다.","pre":["M3-D01","M1-D06"],"std":["9수01-07"]},{"id":"M3-T03","k":"T","name":"제곱근의 대소","text":"a > 0, b > 0일 때 a < b이면 √a < √b이다.","pre":["M3-D01"],"std":["9수01-07"]},{"id":"M3-D02","k":"D","name":"무리수와 실수","text":"유리수가 아닌 수를 무리수라 하고, 유리수와 무리수를 통틀어 실수라 한다.","pre":["M3-D01","M2-T02"],"std":["9수01-08"]},{"id":"M3-T04","k":"T","name":"무리수의 소수 표현","text":"무리수는 순환하지 않는 무한소수로 나타난다. √2, √3처럼 제곱수가 아닌 자연수의 양의 제곱근은 무리수다.","pre":["M3-D02","M1-T01"],"std":["9수01-08"]},{"id":"M3-T05","k":"T","name":"실수와 수직선","text":"모든 실수는 수직선 위의 한 점에 대응하고, 수직선은 실수에 대응하는 점들로 빈틈없이 채워져 있다.","pre":["M3-D02","M1-D06"],"std":["9수01-09"]},{"id":"M3-T06","k":"T","name":"실수의 대소","text":"두 실수 a, b의 대소는 a − b의 부호로 알 수 있다. a − b > 0이면 a > b, a − b = 0이면 a = b, a − b < 0이면 a < b","pre":["M3-T05"],"std":["9수01-09"]},{"id":"M3-T07","k":"T","name":"제곱근의 곱셈·나눗셈","text":"a > 0, b > 0일 때 √a × √b = √(ab), √a ÷ √b = √(a/b), √(a²b) = a√b","pre":["M3-T02"],"std":["9수01-10"],"app":"분모의 유리화(분모와 분자에 같은 근호를 곱하기)"},{"id":"M3-D03","k":"D","name":"분모의 유리화","text":"분모에 근호가 있을 때 분모를 유리수로 고치는 것을 분모의 유리화라 한다.","pre":["M3-T07","E5-T03"],"std":["9수01-10"]},{"id":"M3-T08","k":"T","name":"근호를 포함한 식의 덧셈·뺄셈","text":"근호 안의 수가 같은 것끼리는 동류항처럼 계수끼리 더하고 뺄 수 있다. m√a + n√a = (m+n)√a","pre":["M3-T07","M1-T09"],"std":["9수01-10"]},{"id":"M3-T09","k":"T","name":"곱셈 공식","text":"(a+b)² = a²+2ab+b², (a−b)² = a²−2ab+b², (a+b)(a−b) = a²−b², (x+a)(x+b) = x²+(a+b)x+ab, (ax+b)(cx+d) = acx²+(ad+bc)x+bd","pre":["M1-T08"],"std":["9수02-19"],"app":"다항식의 전개"},{"id":"M3-D04","k":"D","name":"인수분해","text":"하나의 다항식을 두 개 이상의 다항식(인수)의 곱으로 나타내는 것이다. 전개의 반대 과정이다.","pre":["M3-T09","M1-D03"],"std":["9수02-19"]},{"id":"M3-T10","k":"T","name":"인수분해 공식","text":"곱셈 공식의 좌변과 우변을 바꾼 식이 성립한다. a²+2ab+b² = (a+b)², a²−b² = (a+b)(a−b), x²+(a+b)x+ab = (x+a)(x+b), acx²+(ad+bc)x+bd = (ax+b)(cx+d)","pre":["M3-D04"],"std":["9수02-19"],"app":"공통인수 묶기 → 공식으로 인수분해하기"},{"id":"M3-D05","k":"D","name":"이차방정식","text":"모든 항을 좌변으로 이항하여 정리했을 때 ax² + bx + c = 0 (a ≠ 0) 꼴이 되는 방정식이다.","pre":["M1-T10","M3-T09"],"std":["9수02-20"]},{"id":"M3-T11","k":"T","name":"AB = 0의 성질","text":"두 수 또는 두 식 A, B에 대하여 AB = 0이면 A = 0 또는 B = 0이다.","pre":["M1-T06","M3-D05"],"std":["9수02-20"],"app":"인수분해를 이용한 이차방정식의 풀이"},{"id":"M3-D06","k":"D","name":"중근","text":"이차방정식의 두 해가 중복되어 서로 같을 때 그 해를 중근이라 한다.","pre":["M3-T11"],"std":["9수02-20"]},{"id":"M3-T12","k":"T","name":"중근을 가질 조건","text":"이차방정식이 (완전제곱식) = 0 꼴로 나타나면 중근을 가진다.","pre":["M3-D06"],"std":["9수02-20"]},{"id":"M3-T13","k":"T","name":"제곱근을 이용한 풀이","text":"(x + p)² = q (q ≥ 0)이면 x = −p ± √q이다.","pre":["M3-T11","M3-D01"],"std":["9수02-20"],"app":"완전제곱식을 이용한 이차방정식의 풀이"},{"id":"M3-T14","k":"T","name":"근의 공식","text":"ax² + bx + c = 0의 해는 x = (−b ± √(b² − 4ac)) / 2a (단, b² − 4ac ≥ 0)이다.","pre":["M3-T13"],"std":["9수02-20"],"app":"근의 공식을 이용한 풀이"},{"id":"M3-D07","k":"D","name":"이차함수","text":"y = ax² + bx + c (a ≠ 0)처럼 y가 x에 대한 이차식으로 나타나는 함수다.","pre":["M2-D05","M3-D05"],"std":["9수02-21"]},{"id":"M3-D08","k":"D","name":"포물선의 축과 꼭짓점","text":"y = ax²의 그래프와 모양이 같은 곡선을 포물선이라 한다. 포물선의 대칭축을 축, 축과 포물선의 교점을 꼭짓점이라 한다.","pre":["M3-D07","E5-D12"],"std":["9수02-22"]},{"id":"M3-T15","k":"T","name":"y = ax²의 그래프","text":"꼭짓점이 원점이고 축은 y축이다. a > 0이면 아래로 볼록, a < 0이면 위로 볼록하고, a의 절댓값이 클수록 폭이 좁다.","pre":["M3-D08"],"std":["9수02-22"]},{"id":"M3-T16","k":"T","name":"y = a(x−p)² + q의 그래프","text":"y = ax²의 그래프를 x축 방향으로 p, y축 방향으로 q만큼 평행이동한 것이다. 꼭짓점 (p, q), 축 x = p","pre":["M3-T15","M2-T06"],"std":["9수02-22"]},{"id":"M3-T17","k":"T","name":"일반형과 표준형","text":"y = ax² + bx + c는 y = a(x + b/2a)² − (b² − 4ac)/4a로 바꿀 수 있다. 따라서 꼭짓점은 (−b/2a, −(b² − 4ac)/4a)이다.","pre":["M3-T16","M3-T13"],"std":["9수02-22"],"app":"완전제곱식으로 고쳐 꼭짓점·축 찾고 그래프 그리기"},{"id":"M3-D09","k":"D","name":"삼각비","text":"∠C = 90°인 직각삼각형 ABC에서 sin A = BC/AB, cos A = AC/AB, tan A = BC/AC라 한다.","pre":["M2-T19","M2-T22"],"std":["9수03-16"]},{"id":"M3-T18","k":"T","name":"삼각비는 각에 따라 정해진다","text":"∠A의 크기가 같으면 직각삼각형의 크기와 상관없이 sin A, cos A, tan A의 값은 각각 같다.","pre":["M3-D09","M2-T19"],"std":["9수03-16"]},{"id":"M3-T19","k":"T","name":"특수각의 삼각비","text":"sin 30° = 1/2, sin 45° = √2/2, sin 60° = √3/2, cos 30° = √3/2, cos 45° = √2/2, cos 60° = 1/2, tan 30° = √3/3, tan 45° = 1, tan 60° = √3","pre":["M3-D09"],"std":["9수03-16"]},{"id":"M3-T20","k":"T","name":"삼각형의 넓이와 삼각비","text":"두 변의 길이 a, b와 그 끼인각 C(예각)를 알면 삼각형의 넓이는 (1/2)ab sin C다.","pre":["M3-D09","E5-T09"],"std":["9수03-17"],"app":"삼각비로 직각삼각형의 변의 길이·높이 구하기"},{"id":"M3-T21","k":"T","name":"원의 현","text":"원의 중심에서 현에 내린 수선은 그 현을 이등분한다. 한 원에서 중심으로부터 같은 거리에 있는 두 현의 길이는 같다.","pre":["M1-D22","M2-T12"],"std":["9수03-18"]},{"id":"M3-D10","k":"D","name":"원의 접선","text":"원과 한 점에서만 만나는 직선을 원의 접선, 그 점을 접점이라 한다.","pre":["M1-D22"],"std":["9수03-18"]},{"id":"M3-T22","k":"T","name":"원의 접선의 성질","text":"원의 접선은 접점을 지나는 반지름에 수직이다. 원 밖의 한 점에서 그은 두 접선의 길이는 같다.","pre":["M3-T21","M3-D10"],"std":["9수03-18"]},{"id":"M3-D11","k":"D","name":"원주각","text":"원 위의 한 점에서 그은 두 현이 이루는 각이다.","pre":["M1-D22"],"std":["9수03-19"]},{"id":"M3-T23","k":"T","name":"원주각의 성질","text":"한 호에 대한 원주각의 크기는 중심각의 크기의 1/2이고, 한 호에 대한 원주각의 크기는 모두 같다. 반원에 대한 원주각은 90°다.","pre":["M3-D11","M1-T18"],"std":["9수03-19"]},{"id":"M3-T24","k":"T","name":"원에 내접하는 사각형","text":"원에 내접하는 사각형의 대각의 크기의 합은 180°다.","pre":["M3-T23"],"std":["9수03-19"]},{"id":"M3-D12","k":"D","name":"분산과 표준편차","text":"편차 = (변량) − (평균), 분산 = (편차의 제곱의 평균), 표준편차 = √(분산)이다.","pre":["M1-D25","M3-D01"],"std":["9수04-07"]},{"id":"M3-T25","k":"T","name":"편차의 합","text":"편차의 총합은 항상 0이다.","pre":["M3-D12"],"std":["9수04-07"]},{"id":"M3-T26","k":"T","name":"표준편차와 흩어진 정도","text":"자료가 평균 가까이 모여 있을수록 분산과 표준편차가 작고, 넓게 흩어져 있을수록 크다.","pre":["M3-D12"],"std":["9수04-07"],"app":"두 자료의 흩어진 정도 비교"},{"id":"M3-D13","k":"D","name":"상자그림","text":"최솟값, 제1사분위수, 중앙값, 제3사분위수, 최댓값의 다섯 값으로 자료의 분포를 나타낸 그림이다.","pre":["M1-D25"],"std":["9수04-08"]},{"id":"M3-D14","k":"D","name":"산점도와 상관관계","text":"두 변량의 순서쌍을 좌표평면에 나타낸 그림이 산점도다. 한 변량이 커질 때 다른 변량이 대체로 커지면 양의 상관관계, 작아지면 음의 상관관계라 한다.","pre":["M1-D12"],"std":["9수04-09"]}]},
  {"id":"C1","part":"고등","label":"공통수학1","items":[{"id":"C1-T01","k":"T","name":"다항식의 연산 법칙","text":"다항식의 덧셈과 곱셈에서도 교환법칙, 결합법칙, 분배법칙이 성립한다.","pre":["M1-T08","M1-T09"],"std":["10공수1-01-01"],"app":"다항식을 내림차순(오름차순)으로 정리해 계산하기"},{"id":"C1-T02","k":"T","name":"곱셈 공식의 확장","text":"(a+b+c)² = a²+b²+c²+2ab+2bc+2ca, (a±b)³ = a³±3a²b+3ab²±b³, (a±b)(a²∓ab+b²) = a³±b³","pre":["M3-T09"],"std":["10공수1-01-01"]},{"id":"C1-T03","k":"T","name":"다항식의 나눗셈","text":"다항식 A를 B(B ≠ 0)로 나눈 몫을 Q, 나머지를 R이라 하면 A = BQ + R이고, R = 0이거나 R의 차수는 B의 차수보다 낮다.","pre":["C1-T01","E3-T03"],"std":["10공수1-01-01"],"app":"다항식의 나눗셈(세로셈), 조립제법(x−a로 나눌 때 계수만으로 몫과 나머지 구하기)"},{"id":"C1-D01","k":"D","name":"항등식","text":"문자에 어떤 값을 대입해도 항상 참이 되는 등식이다.","pre":["M1-D10"],"std":["10공수1-01-02"]},{"id":"C1-T04","k":"T","name":"항등식의 성질","text":"ax²+bx+c = 0이 x에 대한 항등식이면 a = b = c = 0이다. ax²+bx+c = a'x²+b'x+c'이 항등식이면 a = a', b = b', c = c'이다.","pre":["C1-D01"],"std":["10공수1-01-02"],"app":"미정계수법(계수비교법, 수치대입법)"},{"id":"C1-T05","k":"T","name":"나머지정리","text":"다항식 f(x)를 x−a로 나눈 나머지는 f(a)이다. ax+b로 나눈 나머지는 f(−b/a)이다.","pre":["C1-T03","C1-T04"],"std":["10공수1-01-02"]},{"id":"C1-T06","k":"T","name":"인수정리","text":"다항식 f(x)에서 f(a) = 0이면 f(x)는 x−a로 나누어떨어지고, 그 역도 성립한다.","pre":["C1-T05"],"std":["10공수1-01-02"]},{"id":"C1-T07","k":"T","name":"인수분해 공식의 확장","text":"a²+b²+c²+2ab+2bc+2ca = (a+b+c)², a³±3a²b+3ab²±b³ = (a±b)³, a³±b³ = (a±b)(a²∓ab+b²)","pre":["C1-T02","M3-T10"],"std":["10공수1-01-03"],"app":"인수정리와 조립제법으로 삼차 이상의 다항식 인수분해하기, 삼차·사차방정식의 풀이(인수분해, 치환, 10공수1-02-07)"},{"id":"C1-D02","k":"D","name":"복소수","text":"i² = −1인 수 i를 허수단위라 하고, 실수 a, b에 대하여 a+bi 꼴의 수를 복소수라 한다(a: 실수부분, b: 허수부분). a−bi는 a+bi의 켤레복소수다.","pre":["M3-D02"],"std":["10공수1-02-01"]},{"id":"C1-D03","k":"D","name":"복소수의 상등과 음수의 제곱근","text":"두 복소수는 실수부분과 허수부분이 각각 같을 때 서로 같다고 한다. a > 0일 때 √(−a) = √a i로 정한다.","pre":["C1-D02"],"std":["10공수1-02-01"]},{"id":"C1-T08","k":"T","name":"복소수의 사칙연산","text":"복소수끼리 더하고, 빼고, 곱하고, 0이 아닌 복소수로 나눈 결과도 복소수이며, 실수에서의 교환·결합·분배법칙이 그대로 성립한다.","pre":["C1-D03","C1-T01"],"std":["10공수1-02-01"],"app":"i를 문자처럼 계산하고 i²을 −1로 바꾸기, 분모의 켤레복소수를 곱해 나누기"},{"id":"C1-D04","k":"D","name":"판별식","text":"이차방정식 ax²+bx+c = 0에서 D = b²−4ac를 판별식이라 한다.","pre":["M3-T14","C1-D02"],"std":["10공수1-02-02"]},{"id":"C1-T09","k":"T","name":"판별식과 근","text":"계수가 실수일 때 D > 0이면 서로 다른 두 실근, D = 0이면 중근, D < 0이면 서로 다른 두 허근을 갖는다.","pre":["C1-D04"],"std":["10공수1-02-02"]},{"id":"C1-T10","k":"T","name":"근과 계수의 관계","text":"ax²+bx+c = 0의 두 근을 α, β라 하면 α+β = −b/a, αβ = c/a이다.","pre":["M3-T14","C1-D02","C1-T09"],"std":["10공수1-02-03"],"app":"두 근이 주어진 이차방정식 만들기"},{"id":"C1-T11","k":"T","name":"이차방정식과 이차함수","text":"y = ax²+bx+c의 그래프와 x축의 교점의 x좌표는 ax²+bx+c = 0의 실근이다. 따라서 D > 0이면 두 점, D = 0이면 한 점에서 만나고(접하고), D < 0이면 만나지 않는다.","pre":["C1-T09","M3-T17"],"std":["10공수1-02-04"]},{"id":"C1-T12","k":"T","name":"이차함수와 직선","text":"y = ax²+bx+c의 그래프와 직선 y = mx+n은 ax²+bx+c = mx+n의 판별식이 D > 0이면 두 점에서 만나고, D = 0이면 접하고, D < 0이면 만나지 않는다.","pre":["C1-T11"],"std":["10공수1-02-05"]},{"id":"C1-T13","k":"T","name":"제한된 범위에서의 최대·최소","text":"f(x) = a(x−p)²+q의 α ≤ x ≤ β에서의 최댓값과 최솟값은, p가 범위 안에 있으면 f(p), f(α), f(β) 중에, 범위 밖에 있으면 f(α), f(β) 중에 있다.","pre":["M3-T17"],"std":["10공수1-02-06"]},{"id":"C1-D05","k":"D","name":"연립부등식과 해","text":"두 개 이상의 부등식을 한 쌍으로 묶은 것을 연립부등식이라 하고, 각 부등식의 해의 공통부분을 연립부등식의 해라 한다.","pre":["M2-D03"],"std":["10공수1-02-09"],"app":"연립일차부등식의 풀이(수직선에서 공통부분 찾기)"},{"id":"C1-T14","k":"T","name":"절댓값을 포함한 부등식","text":"a > 0일 때 (x의 절댓값) < a ⇔ −a < x < a, (x의 절댓값) > a ⇔ x < −a 또는 x > a이다.","pre":["C1-D05","M1-D06"],"std":["10공수1-02-10"],"app":"그 밖의 경우는 절댓값 안의 부호로 범위를 나누어 풀기"},{"id":"C1-T15","k":"T","name":"이차부등식","text":"a > 0이고 ax²+bx+c = 0의 두 실근이 α < β이면, ax²+bx+c > 0의 해는 x < α 또는 x > β, ax²+bx+c < 0의 해는 α < x < β다.","pre":["C1-T11","C1-D05"],"std":["10공수1-02-11"],"app":"그래프로 이차부등식 풀기, 연립이차부등식"},{"id":"C1-T16","k":"T","name":"합의 법칙과 곱의 법칙","text":"동시에 일어나지 않는 두 사건 A, B의 경우의 수가 m, n이면 A 또는 B가 일어나는 경우의 수는 m+n이다. 잇따라 일어나면 m×n이다.","pre":["M2-T24"],"std":["10공수1-03-01"]},{"id":"C1-D06","k":"D","name":"순열과 계승","text":"서로 다른 n개에서 r개를 택하여 일렬로 나열하는 것을 순열이라 하고, 그 수를 nPr로 쓴다. n! = n(n−1)×…×2×1이고, 0! = 1로 정한다.","pre":["C1-T16"],"std":["10공수1-03-02"]},{"id":"C1-T17","k":"T","name":"순열의 수","text":"nPr = n(n−1)(n−2)×…×(n−r+1) = n!/(n−r)! (0 ≤ r ≤ n)","pre":["C1-D06","C1-T16"],"std":["10공수1-03-02"]},{"id":"C1-D07","k":"D","name":"조합","text":"서로 다른 n개에서 순서를 생각하지 않고 r개를 택하는 것을 조합이라 하고, 그 수를 nCr로 쓴다.","pre":["C1-D06"],"std":["10공수1-03-03"]},{"id":"C1-T18","k":"T","name":"조합의 수","text":"nCr = nPr/r! = n!/(r!(n−r)!)","pre":["C1-D07","C1-T17"],"std":["10공수1-03-03"]},{"id":"C1-T19","k":"T","name":"조합의 성질","text":"nCr = nC(n−r), nCr = (n−1)C(r−1) + (n−1)Cr","pre":["C1-T18"],"std":["10공수1-03-03"]},{"id":"C1-D08","k":"D","name":"행렬","text":"수나 문자를 직사각형 모양으로 배열하여 괄호로 묶은 것이다. m개의 행과 n개의 열이면 m×n 행렬, i행 j열의 수를 (i, j) 성분이라 한다.","pre":["M1-D12"],"std":["10공수1-04-01"]},{"id":"C1-D09","k":"D","name":"행렬의 덧셈·뺄셈·실수배·곱셈","text":"같은 꼴의 두 행렬의 합과 차는 같은 위치의 성분끼리 더하고 뺀 행렬이다. 실수 k에 대하여 kA는 A의 각 성분에 k를 곱한 행렬이다. 곱 AB는 A의 열의 개수와 B의 행의 개수가 같을 때만 정하고, (i, j) 성분은 A의 i행과 B의 j열의 성분을 차례로 곱해 더한 값이다.","pre":["C1-D08"],"std":["10공수1-04-02"]},{"id":"C1-T20","k":"T","name":"행렬의 곱의 성질","text":"행렬의 곱셈에서 결합법칙과 분배법칙은 성립하지만, AB와 BA는 일반적으로 같지 않다(교환법칙이 성립하지 않는다).","pre":["C1-D09"],"std":["10공수1-04-02"]}]},
  {"id":"C2","part":"고등","label":"공통수학2","items":[{"id":"C2-T01","k":"T","name":"두 점 사이의 거리","text":"두 점 (x₁, y₁), (x₂, y₂) 사이의 거리는 √((x₂−x₁)² + (y₂−y₁)²)이다.","pre":["M2-T22","M1-D12"],"std":["10공수2-01-01"]},{"id":"C2-T02","k":"T","name":"내분점","text":"두 점 A(x₁, y₁), B(x₂, y₂)를 m : n으로 내분하는 점은 ((mx₂+nx₁)/(m+n), (my₂+ny₁)/(m+n))이다. m = n이면 중점이다.","pre":["C2-T01","M2-T20"],"std":["10공수2-01-01"]},{"id":"C2-T03","k":"T","name":"직선의 방정식","text":"한 점 (x₁, y₁)을 지나고 기울기가 m인 직선은 y−y₁ = m(x−x₁)이다. 모든 직선은 ax+by+c = 0 꼴로 나타낼 수 있다.","pre":["M2-T08","M2-T09"],"std":["10공수2-01-02"]},{"id":"C2-T04","k":"T","name":"두 직선의 평행·수직","text":"두 직선 y = mx+n, y = m'x+n'에서 평행 ⇔ m = m', n ≠ n', 수직 ⇔ mm' = −1이다.","pre":["C2-T03","M2-T10"],"std":["10공수2-01-02"]},{"id":"C2-T05","k":"T","name":"점과 직선 사이의 거리","text":"점 (x₁, y₁)과 직선 ax+by+c = 0 사이의 거리는 (ax₁+by₁+c의 절댓값) ÷ √(a²+b²)이다.","pre":["C2-T03","M1-D18"],"std":["10공수2-01-03"]},{"id":"C2-T06","k":"T","name":"원의 방정식","text":"중심이 (a, b)이고 반지름이 r인 원의 방정식은 (x−a)² + (y−b)² = r²이다. 전개하면 x²+y²+Ax+By+C = 0 꼴이다.","pre":["C2-T01","E3-D09"],"std":["10공수2-01-04"]},{"id":"C2-T07","k":"T","name":"원과 직선의 위치 관계","text":"원의 중심과 직선 사이의 거리를 d, 반지름을 r이라 할 때 d < r이면 두 점에서 만나고, d = r이면 접하고, d > r이면 만나지 않는다.","pre":["C2-T06","C2-T05","C1-T09"],"std":["10공수2-01-05"],"app":"판별식으로 위치 관계 판단하기"},{"id":"C2-T08","k":"T","name":"원의 접선의 방정식","text":"원 x²+y² = r² 위의 점 (x₁, y₁)에서의 접선은 x₁x + y₁y = r², 기울기가 m인 접선은 y = mx ± r√(m²+1)이다.","pre":["C2-T07","M3-T22"],"std":["10공수2-01-05"]},{"id":"C2-D01","k":"D","name":"평행이동","text":"점 (x, y)를 x축 방향으로 a, y축 방향으로 b만큼 옮겨 점 (x+a, y+b)로 보내는 것을 평행이동이라 한다.","pre":["M3-T16"],"std":["10공수2-01-06"]},{"id":"C2-T09","k":"T","name":"도형의 평행이동","text":"방정식 f(x, y) = 0이 나타내는 도형을 x축 방향으로 a, y축 방향으로 b만큼 평행이동한 도형의 방정식은 f(x−a, y−b) = 0이다.","pre":["C2-D01"],"std":["10공수2-01-06"]},{"id":"C2-D02","k":"D","name":"대칭이동","text":"점 (x, y)를 x축에 대하여 (x, −y)로, y축에 대하여 (−x, y)로, 원점에 대하여 (−x, −y)로, 직선 y = x에 대하여 (y, x)로 옮기는 것을 대칭이동이라 한다.","pre":["C2-D01","E5-D12"],"std":["10공수2-01-07"]},{"id":"C2-T10","k":"T","name":"도형의 대칭이동","text":"도형 f(x, y) = 0을 x축, y축, 원점, 직선 y = x에 대하여 대칭이동한 도형은 각각 f(x, −y) = 0, f(−x, y) = 0, f(−x, −y) = 0, f(y, x) = 0이다.","pre":["C2-D02","C2-T09"],"std":["10공수2-01-07"]},{"id":"C2-D03","k":"D","name":"집합과 부분집합","text":"대상이 분명한 것들의 모임을 집합, 집합을 이루는 것을 원소라 한다. A의 모든 원소가 B에 속하면 A를 B의 부분집합(A ⊂ B)이라 하고, 원소가 하나도 없는 집합을 공집합(∅)이라 한다.","pre":["E2-D12"],"std":["10공수2-02-01","10공수2-02-02"]},{"id":"C2-T11","k":"T","name":"부분집합의 성질과 개수","text":"공집합은 모든 집합의 부분집합이고, 모든 집합은 자기 자신의 부분집합이다. A ⊂ B이고 B ⊂ C이면 A ⊂ C이다. 원소가 n개인 집합의 부분집합은 2ⁿ개다.","pre":["C2-D03","M2-T24"],"std":["10공수2-02-02"]},{"id":"C2-D04","k":"D","name":"집합의 연산","text":"합집합 A∪B, 교집합 A∩B, 여집합 Aᶜ(전체집합 U에서 A에 속하지 않는 원소의 집합), 차집합 A−B(A에는 속하고 B에는 속하지 않는 원소의 집합)다.","pre":["C2-D03"],"std":["10공수2-02-03"]},{"id":"C2-T12","k":"T","name":"드모르간의 법칙","text":"(A∪B)ᶜ = Aᶜ∩Bᶜ, (A∩B)ᶜ = Aᶜ∪Bᶜ","pre":["C2-D04"],"std":["10공수2-02-03"]},{"id":"C2-T13","k":"T","name":"합집합의 원소의 개수","text":"n(A∪B) = n(A) + n(B) − n(A∩B)","pre":["C2-D04"],"std":["10공수2-02-03"]},{"id":"C2-D05","k":"D","name":"명제와 조건","text":"참·거짓을 분명하게 판별할 수 있는 문장이나 식이 명제다. 변수의 값에 따라 참·거짓이 정해지는 것이 조건이고, 조건을 참이 되게 하는 원소의 집합이 진리집합이다. ‘모든’과 ‘어떤’이 들어간 명제도 있다.","pre":["C2-D03"],"std":["10공수2-02-04"]},{"id":"C2-T14","k":"T","name":"명제와 진리집합","text":"조건 p, q의 진리집합을 P, Q라 할 때, 명제 p → q가 참이면 P ⊂ Q이고 그 역도 성립한다.","pre":["C2-D05"],"std":["10공수2-02-04"]},{"id":"C2-D06","k":"D","name":"역과 대우","text":"명제 p → q에 대하여 q → p는 역, ~q → ~p는 대우다.","pre":["C2-D05"],"std":["10공수2-02-05"]},{"id":"C2-T15","k":"T","name":"대우의 참·거짓","text":"명제가 참이면 그 대우도 참이고, 거짓이면 대우도 거짓이다. 역은 참·거짓이 다를 수 있다.","pre":["C2-D06","C2-T14"],"std":["10공수2-02-05"],"app":"대우를 이용한 증명, 귀류법(결론을 부정해 모순 보이기, 10공수2-02-07)"},{"id":"C2-D07","k":"D","name":"충분조건과 필요조건","text":"p → q가 참일 때 p는 q이기 위한 충분조건, q는 p이기 위한 필요조건이다. 양쪽 모두 참이면 필요충분조건이다.","pre":["C2-T14"],"std":["10공수2-02-06"]},{"id":"C2-T16","k":"T","name":"절대부등식","text":"a > 0, b > 0일 때 (a+b)/2 ≥ √(ab) (등호는 a = b일 때). 실수 a, b, x, y에 대하여 (a²+b²)(x²+y²) ≥ (ax+by)²","pre":["C2-T15","M2-T04"],"std":["10공수2-02-08"]},{"id":"C2-D08","k":"D","name":"함수와 정의역·치역","text":"집합 X의 각 원소에 집합 Y의 원소가 오직 하나씩 대응할 때 f : X → Y를 함수라 한다. X는 정의역, Y는 공역, 함숫값들의 집합은 치역이다.","pre":["M2-D05","C2-D03"],"std":["10공수2-03-01"]},{"id":"C2-D09","k":"D","name":"일대일함수와 일대일대응","text":"정의역의 서로 다른 원소가 서로 다른 함숫값을 가지면 일대일함수, 그중 치역과 공역이 같으면 일대일대응이다. f(x) = x는 항등함수, f(x) = c는 상수함수다.","pre":["C2-D08"],"std":["10공수2-03-01"]},{"id":"C2-D10","k":"D","name":"합성함수","text":"두 함수 f : X → Y, g : Y → Z에 대하여 (g∘f)(x) = g(f(x))를 f와 g의 합성함수라 한다.","pre":["C2-D08"],"std":["10공수2-03-02"]},{"id":"C2-T17","k":"T","name":"합성함수의 성질","text":"결합법칙 h∘(g∘f) = (h∘g)∘f는 성립하지만, 교환법칙 g∘f = f∘g는 일반적으로 성립하지 않는다.","pre":["C2-D10"],"std":["10공수2-03-02"]},{"id":"C2-D11","k":"D","name":"역함수","text":"f가 일대일대응일 때, y = f(x)인 x를 y에 대응시키는 함수를 f의 역함수라 하고 f⁻¹로 쓴다.","pre":["C2-D09","C2-D10"],"std":["10공수2-03-03"]},{"id":"C2-T18","k":"T","name":"역함수의 성질과 그래프","text":"(f⁻¹∘f)(x) = x, (f∘f⁻¹)(y) = y이다. y = f(x)의 그래프와 y = f⁻¹(x)의 그래프는 직선 y = x에 대하여 대칭이다.","pre":["C2-D11","C2-D02"],"std":["10공수2-03-03"]},{"id":"C2-D12","k":"D","name":"유리함수","text":"y = (다항식)/(다항식) 꼴로 나타낸 함수를 유리함수라 한다. 특별한 말이 없으면 정의역은 분모가 0이 아닌 실수 전체다.","pre":["M1-T12","C2-D01"],"std":["10공수2-03-04"]},{"id":"C2-T19","k":"T","name":"유리함수의 그래프","text":"y = k/(x−p) + q의 그래프는 y = k/x의 그래프를 x축 방향으로 p, y축 방향으로 q만큼 평행이동한 것이고, 점근선은 x = p, y = q다.","pre":["C2-D12","C2-T09"],"std":["10공수2-03-04"]},{"id":"C2-D13","k":"D","name":"무리함수","text":"근호 안에 문자가 있는 식으로 나타낸 함수를 무리함수라 한다. 특별한 말이 없으면 정의역은 근호 안이 0 이상인 실수 전체다.","pre":["M3-D01","C2-D01"],"std":["10공수2-03-05"]},{"id":"C2-T20","k":"T","name":"무리함수의 그래프","text":"y = √(a(x−p)) + q의 그래프는 y = √(ax)의 그래프를 x축 방향으로 p, y축 방향으로 q만큼 평행이동한 것이다. y = √(ax)와 y = x²/a (x ≥ 0)은 서로 역함수다.","pre":["C2-D13","C2-T09","C2-T18"],"std":["10공수2-03-05"]}]},
  {"id":"AL","part":"고등","label":"대수","items":[{"id":"AL-D01","k":"D","name":"거듭제곱근","text":"n제곱하여 a가 되는 수를 a의 n제곱근이라 하고, 이 중 실수인 것을 생각한다. n이 홀수이면 실수인 n제곱근은 하나뿐이고 ⁿ√a로 나타낸다. n이 짝수이고 a > 0이면 양수인 것을 ⁿ√a, 음수인 것을 −ⁿ√a로 나타낸다.","pre":["M3-D01"],"std":["12대수01-01"]},{"id":"AL-T01","k":"T","name":"거듭제곱근의 성질","text":"a > 0, b > 0일 때 ⁿ√a × ⁿ√b = ⁿ√(ab), ⁿ√a ÷ ⁿ√b = ⁿ√(a/b), (ⁿ√a)ᵐ = ⁿ√(aᵐ), ᵐ√(ⁿ√a) = ᵐⁿ√a","pre":["AL-D01","M3-T07"],"std":["12대수01-01"]},{"id":"AL-D02","k":"D","name":"지수의 확장","text":"a ≠ 0일 때 a⁰ = 1, a⁻ⁿ = 1/aⁿ으로 정한다. a > 0일 때 a^(m/n) = ⁿ√(aᵐ)으로 정하고, 실수 지수까지 넓힌다.","pre":["M2-T03","AL-D01"],"std":["12대수01-02"]},{"id":"AL-T02","k":"T","name":"지수법칙 (실수 지수)","text":"a > 0, b > 0이고 x, y가 실수일 때 aˣaʸ = aˣ⁺ʸ, aˣ ÷ aʸ = aˣ⁻ʸ, (aˣ)ʸ = aˣʸ, (ab)ˣ = aˣbˣ","pre":["AL-D02"],"std":["12대수01-03"]},{"id":"AL-D03","k":"D","name":"로그","text":"a > 0, a ≠ 1, N > 0일 때 aˣ = N을 만족하는 x를 logₐN으로 나타낸다(a: 밑, N: 진수).","pre":["AL-D02"],"std":["12대수01-04"]},{"id":"AL-T03","k":"T","name":"로그의 성질","text":"logₐ1 = 0, logₐa = 1, logₐMN = logₐM + logₐN, logₐ(M/N) = logₐM − logₐN, logₐMᵏ = k logₐM","pre":["AL-D03","AL-T02"],"std":["12대수01-04"]},{"id":"AL-T04","k":"T","name":"밑의 변환","text":"logₐb = (log_c b) / (log_c a) (c > 0, c ≠ 1)이다. 따라서 b > 0, b ≠ 1이면 logₐb × log_b a = 1이다.","pre":["AL-T03"],"std":["12대수01-04"]},{"id":"AL-D04","k":"D","name":"상용로그","text":"밑이 10인 로그다. log₁₀N을 간단히 log N으로 쓴다.","pre":["AL-D03"],"std":["12대수01-05"]},{"id":"AL-D05","k":"D","name":"지수함수","text":"a > 0, a ≠ 1일 때 y = aˣ을 a를 밑으로 하는 지수함수라 한다.","pre":["AL-D02","C2-D08"],"std":["12대수01-06"]},{"id":"AL-T05","k":"T","name":"지수함수의 그래프","text":"y = aˣ의 그래프는 점 (0, 1)을 지나고 점근선은 x축이다. 치역은 양의 실수 전체이고, a > 1이면 증가, 0 < a < 1이면 감소한다.","pre":["AL-D05"],"std":["12대수01-07"]},{"id":"AL-D06","k":"D","name":"로그함수","text":"지수함수 y = aˣ의 역함수 y = logₐx를 로그함수라 한다.","pre":["AL-D05","AL-D03","C2-D11"],"std":["12대수01-06"]},{"id":"AL-T06","k":"T","name":"로그함수의 그래프","text":"y = logₐx의 그래프는 y = aˣ의 그래프와 직선 y = x에 대하여 대칭이고, 점 (1, 0)을 지나며 점근선은 y축이다. a > 1이면 증가, 0 < a < 1이면 감소한다.","pre":["AL-D06","AL-T05","C2-T18"],"std":["12대수01-07"]},{"id":"AL-T07","k":"T","name":"지수·로그의 대소","text":"a > 1이면 x₁ < x₂ ⇔ a^(x₁) < a^(x₂), 0 < a < 1이면 부등호가 반대다. 로그도 같다(진수는 양수).","pre":["AL-T05","AL-T06"],"std":["12대수01-08"],"app":"지수·로그 방정식과 부등식의 풀이"},{"id":"AL-D07","k":"D","name":"일반각과 호도법","text":"동경 OP가 시초선과 이루는 한 각을 α라 하면 동경이 나타내는 각은 360°n + α(n은 정수)다. 반지름과 길이가 같은 호에 대한 중심각의 크기를 1라디안이라 한다.","pre":["M1-D22","E4-D03"],"std":["12대수02-01"]},{"id":"AL-T08","k":"T","name":"호도법과 부채꼴","text":"180° = π라디안이다. 반지름 r, 중심각 θ인 부채꼴의 호의 길이는 l = rθ, 넓이는 S = (1/2)r²θ = (1/2)rl이다.","pre":["AL-D07","M1-T21"],"std":["12대수02-01"]},{"id":"AL-D08","k":"D","name":"삼각함수","text":"원점 중심, 반지름 r인 원 위의 점 P(x, y)에 대하여 동경 OP가 나타내는 각을 θ라 할 때 sinθ = y/r, cosθ = x/r, tanθ = y/x (x ≠ 0)이다.","pre":["M3-D09","AL-D07"],"std":["12대수02-02"]},{"id":"AL-T09","k":"T","name":"삼각함수 사이의 관계","text":"tanθ = sinθ/cosθ, sin²θ + cos²θ = 1","pre":["AL-D08","M2-T22"],"std":["12대수02-02"]},{"id":"AL-D09","k":"D","name":"주기함수","text":"모든 x에 대하여 f(x+p) = f(x)를 만족하는 0이 아닌 상수 p가 있을 때 f를 주기함수라 하고, 그러한 p 중 가장 작은 양수를 주기라 한다.","pre":["AL-D08"],"std":["12대수02-02"]},{"id":"AL-T10","k":"T","name":"삼각함수의 그래프","text":"y = sin x, y = cos x는 주기 2π, 치역 −1 이상 1 이하다. y = tan x는 주기 π이고 점근선은 x = nπ + π/2 (n은 정수)다. y = a sin(bx + c) + d의 최댓값은 (a의 절댓값) + d, 주기는 2π ÷ (b의 절댓값)이다.","pre":["AL-D09","AL-T09"],"std":["12대수02-02"],"app":"삼각함수가 포함된 방정식·부등식 풀이"},{"id":"AL-T11","k":"T","name":"사인법칙","text":"삼각형 ABC의 외접원의 반지름을 R이라 하면 a/sinA = b/sinB = c/sinC = 2R이다.","pre":["AL-D08","M3-T23"],"std":["12대수02-03"]},{"id":"AL-T12","k":"T","name":"코사인법칙","text":"삼각형 ABC에서 a² = b² + c² − 2bc cosA이다.","pre":["AL-D08","M2-T22"],"std":["12대수02-03"]},{"id":"AL-T13","k":"T","name":"삼각형의 넓이","text":"삼각형 ABC의 넓이는 S = (1/2)ab sinC이다.","pre":["AL-D08","M3-T20"],"std":["12대수02-03"]},{"id":"AL-D10","k":"D","name":"수열","text":"차례로 나열한 수의 열이다. n번째 항 aₙ을 n에 대한 식으로 나타낸 것이 일반항이다.","pre":["C2-D08"],"std":["12대수03-01"]},{"id":"AL-D11","k":"D","name":"등차수열","text":"첫째항부터 차례로 일정한 수 d(공차)를 더하여 만든 수열이다.","pre":["AL-D10"],"std":["12대수03-02"]},{"id":"AL-T14","k":"T","name":"등차수열의 일반항과 합","text":"첫째항 a, 공차 d이면 aₙ = a + (n−1)d, Sₙ = n(2a + (n−1)d)/2 = n(a + l)/2 (l은 끝항)이다.","pre":["AL-D11"],"std":["12대수03-02"]},{"id":"AL-D12","k":"D","name":"등비수열","text":"첫째항부터 차례로 일정한 수 r(공비)을 곱하여 만든 수열이다.","pre":["AL-D10"],"std":["12대수03-03"]},{"id":"AL-T15","k":"T","name":"등비수열의 일반항과 합","text":"첫째항 a, 공비 r이면 aₙ = arⁿ⁻¹이고, r ≠ 1이면 Sₙ = a(rⁿ − 1)/(r − 1), r = 1이면 Sₙ = na다.","pre":["AL-D12"],"std":["12대수03-03"]},{"id":"AL-D13","k":"D","name":"합의 기호 Σ","text":"a₁ + a₂ + … + aₙ을 Σ(k=1부터 n까지) aₖ로 나타낸다.","pre":["AL-D10"],"std":["12대수03-04"]},{"id":"AL-T16","k":"T","name":"Σ의 성질","text":"Σ(aₖ ± bₖ) = Σaₖ ± Σbₖ, Σcaₖ = cΣaₖ, Σc = cn (c는 상수)","pre":["AL-D13"],"std":["12대수03-04"]},{"id":"AL-T17","k":"T","name":"자연수의 거듭제곱의 합","text":"Σk = n(n+1)/2, Σk² = n(n+1)(2n+1)/6, Σk³ = {n(n+1)/2}²","pre":["AL-T16"],"std":["12대수03-05"]},{"id":"AL-T18","k":"T","name":"부분분수와 합","text":"1/(k(k+1)) = 1/k − 1/(k+1)이므로 Σ(k=1부터 n까지) 1/(k(k+1)) = 1 − 1/(n+1) = n/(n+1)이다.","pre":["AL-T16"],"std":["12대수03-05"],"app":"부분분수로 나누어 여러 가지 수열의 합 구하기"},{"id":"AL-D14","k":"D","name":"수열의 귀납적 정의","text":"첫째항과 이웃하는 항 사이의 관계식(점화식)으로 수열을 정하는 것이다.","pre":["AL-D10"],"std":["12대수03-06"]},{"id":"AL-D15","k":"D","name":"수학적 귀납법의 원리","text":"(i) n = 1일 때 명제가 참이고, (ii) n = k일 때 참이라고 가정하면 n = k+1일 때도 참임을 보이면, 모든 자연수 n에 대하여 명제가 참이라고 받아들인다.","pre":["AL-D14","C2-D05"],"std":["12대수03-07"],"app":"수학적 귀납법으로 증명하기"}]},
  {"id":"CA","part":"고등","label":"미적분Ⅰ","items":[{"id":"CA-D01","k":"D","name":"함수의 극한","text":"x가 a가 아니면서 a에 한없이 가까워질 때 f(x)가 일정한 값 L에 한없이 가까워지면 f(x)는 L에 수렴한다고 하고 lim(x→a) f(x) = L로 나타낸다. 수렴하지 않으면 발산한다고 한다.","pre":["C2-D08"],"std":["12미적Ⅰ-01-01"]},{"id":"CA-D02","k":"D","name":"좌극한과 우극한","text":"x가 a보다 작으면서 a에 가까워질 때의 극한이 좌극한, a보다 크면서 가까워질 때의 극한이 우극한이다.","pre":["CA-D01"],"std":["12미적Ⅰ-01-01"]},{"id":"CA-T01","k":"T","name":"극한이 존재할 조건","text":"lim(x→a) f(x) = L ⇔ 좌극한과 우극한이 모두 존재하고 그 값이 L로 같다.","pre":["CA-D02"],"std":["12미적Ⅰ-01-01"]},{"id":"CA-T02","k":"T","name":"함수의 극한에 대한 성질","text":"두 함수가 수렴하면 합·차·실수배·곱의 극한은 각 극한의 합·차·실수배·곱이고, 분모의 극한이 0이 아니면 몫의 극한은 극한의 몫이다.","pre":["CA-D01"],"std":["12미적Ⅰ-01-02"]},{"id":"CA-T03","k":"T","name":"분모가 0으로 갈 때","text":"lim f(x)/g(x)가 수렴하고 lim g(x) = 0이면 lim f(x) = 0이다.","pre":["CA-T02"],"std":["12미적Ⅰ-01-02"],"app":"미정계수 구하기"},{"id":"CA-D03","k":"D","name":"연속","text":"f(a)가 정의되고, lim(x→a) f(x)가 존재하며, 그 값이 f(a)와 같을 때 f는 x = a에서 연속이라 한다. 구간의 모든 점에서 연속이면 그 구간에서 연속이다.","pre":["CA-T01"],"std":["12미적Ⅰ-01-03"]},{"id":"CA-T04","k":"T","name":"연속함수의 성질","text":"두 함수가 x = a에서 연속이면 합·차·실수배·곱, 분모가 0이 아닌 몫도 연속이다. 다항함수는 모든 실수에서 연속이다.","pre":["CA-D03","CA-T02"],"std":["12미적Ⅰ-01-04"]},{"id":"CA-T05","k":"T","name":"최대·최소 정리","text":"닫힌구간 [a, b]에서 연속인 함수는 이 구간에서 반드시 최댓값과 최솟값을 갖는다.","pre":["CA-D03"],"std":["12미적Ⅰ-01-04"]},{"id":"CA-T06","k":"T","name":"사잇값 정리","text":"f가 [a, b]에서 연속이고 f(a) ≠ f(b)이면, f(a)와 f(b) 사이의 임의의 값 k에 대하여 f(c) = k인 c가 (a, b)에 적어도 하나 있다. 특히 f(a)f(b) < 0이면 f(x) = 0의 실근이 (a, b)에 적어도 하나 있다.","pre":["CA-D03"],"std":["12미적Ⅰ-01-04"]},{"id":"CA-D04","k":"D","name":"평균변화율","text":"x의 값이 a에서 b까지 변할 때 (f(b) − f(a)) ÷ (b − a)를 평균변화율이라 한다.","pre":["M2-D08"],"std":["12미적Ⅰ-02-01"]},{"id":"CA-D05","k":"D","name":"미분계수","text":"f'(a) = lim(h→0) (f(a+h) − f(a)) / h. 이 극한이 존재하면 f는 x = a에서 미분가능하다고 한다.","pre":["CA-D04","CA-D01"],"std":["12미적Ⅰ-02-01"]},{"id":"CA-D06","k":"D","name":"접선과 미분계수","text":"곡선 y = f(x) 위의 점 (a, f(a))를 지나고 기울기가 f'(a)인 직선을 그 점에서의 접선이라 한다.","pre":["CA-D05"],"std":["12미적Ⅰ-02-01"]},{"id":"CA-T07","k":"T","name":"미분가능성과 연속성","text":"x = a에서 미분가능하면 x = a에서 연속이다. 그 역은 성립하지 않는다. (예: y = (x의 절댓값)은 x = 0에서 연속이지만 미분가능하지 않다.)","pre":["CA-D05","CA-D03"],"std":["12미적Ⅰ-02-02"]},{"id":"CA-D07","k":"D","name":"도함수","text":"미분가능한 함수 f에서 각 x에 미분계수 f'(x)를 대응시킨 함수다. f'(x) = lim(h→0) (f(x+h) − f(x)) / h","pre":["CA-D05"],"std":["12미적Ⅰ-02-03"]},{"id":"CA-T08","k":"T","name":"y = xⁿ의 도함수","text":"n이 자연수일 때 (xⁿ)' = nxⁿ⁻¹, 상수함수의 도함수는 0이다.","pre":["CA-D07","C1-T03"],"std":["12미적Ⅰ-02-03"]},{"id":"CA-T09","k":"T","name":"미분법","text":"{cf(x)}' = cf'(x), {f(x) ± g(x)}' = f'(x) ± g'(x), {f(x)g(x)}' = f'(x)g(x) + f(x)g'(x)","pre":["CA-T08"],"std":["12미적Ⅰ-02-04"],"app":"다항함수 미분하기"},{"id":"CA-T10","k":"T","name":"접선의 방정식","text":"곡선 y = f(x) 위의 점 (a, f(a))에서의 접선은 y − f(a) = f'(a)(x − a)이다.","pre":["CA-D06","C2-T03"],"std":["12미적Ⅰ-02-05"]},{"id":"CA-D08","k":"D","name":"증가와 감소","text":"구간의 임의의 x₁ < x₂에 대하여 f(x₁) < f(x₂)이면 증가, f(x₁) > f(x₂)이면 감소한다고 한다.","pre":["C2-D08"],"std":["12미적Ⅰ-02-07"]},{"id":"CA-D09","k":"D","name":"극대와 극소","text":"x = a를 포함하는 어떤 열린구간에서 f(a)가 가장 크면 극대(극댓값 f(a)), 가장 작으면 극소(극솟값 f(a))라 한다.","pre":["CA-D08"],"std":["12미적Ⅰ-02-07"]},{"id":"CA-T11","k":"T","name":"극값과 미분계수","text":"미분가능한 함수 f가 x = a에서 극값을 가지면 f'(a) = 0이다.","pre":["CA-D05","CA-D09"],"std":["12미적Ⅰ-02-06"]},{"id":"CA-T12","k":"T","name":"롤의 정리와 평균값 정리","text":"f가 [a, b]에서 연속이고 (a, b)에서 미분가능하면 f'(c) = (f(b) − f(a)) / (b − a)인 c가 (a, b)에 적어도 하나 있다. f(a) = f(b)이면 f'(c) = 0(롤의 정리)이다.","pre":["CA-T05","CA-D04","CA-T11"],"std":["12미적Ⅰ-02-06"]},{"id":"CA-T13","k":"T","name":"도함수와 증감","text":"구간에서 f'(x) > 0이면 f는 증가하고, f'(x) < 0이면 감소한다.","pre":["CA-D08","CA-T12"],"std":["12미적Ⅰ-02-07"]},{"id":"CA-T14","k":"T","name":"극값의 판정","text":"f'(a) = 0이고 x = a의 좌우에서 f'(x)의 부호가 +에서 −로 바뀌면 극대, −에서 +로 바뀌면 극소다.","pre":["CA-T11","CA-T13"],"std":["12미적Ⅰ-02-07"],"app":"증감표 만들기"},{"id":"CA-T15","k":"T","name":"방정식의 실근과 그래프","text":"방정식 f(x) = k의 실근의 개수는 y = f(x)의 그래프와 직선 y = k의 교점의 개수와 같다.","pre":["CA-T14"],"std":["12미적Ⅰ-02-08","12미적Ⅰ-02-09"],"app":"증감표로 그래프의 개형 그리기, 최대·최소 활용, 부등식이 성립함을 보이기"},{"id":"CA-T16","k":"T","name":"속도와 가속도","text":"수직선 위를 움직이는 점의 시각 t에서의 위치가 x(t)이면 속도 v = x'(t), 가속도 a = v'(t)이다.","pre":["CA-D07"],"std":["12미적Ⅰ-02-10"]},{"id":"CA-D10","k":"D","name":"부정적분","text":"F'(x) = f(x)일 때 F를 f의 부정적분(원시함수)이라 하고 ∫f(x)dx = F(x) + C로 나타낸다(C는 적분상수).","pre":["CA-D07"],"std":["12미적Ⅰ-03-01"]},{"id":"CA-T17","k":"T","name":"다항함수의 부정적분","text":"n이 0 또는 자연수일 때 ∫xⁿdx = xⁿ⁺¹/(n+1) + C이다. ∫kf(x)dx = k∫f(x)dx, ∫{f(x) ± g(x)}dx = ∫f(x)dx ± ∫g(x)dx","pre":["CA-D10","CA-T08"],"std":["12미적Ⅰ-03-02"]},{"id":"CA-D11","k":"D","name":"정적분","text":"닫힌구간 [a, b]에서 연속인 f에 대하여 그래프와 x축 사이의 넓이(x축 아래는 음수로)를 나타내는 값을 ∫(a부터 b까지) f(x)dx로 나타낸다.","pre":["CA-D03","E5-D10"],"std":["12미적Ⅰ-03-03"]},{"id":"CA-T18","k":"T","name":"정적분의 성질","text":"∫(a→a) f = 0, ∫(b→a) f = −∫(a→b) f, ∫(a→c) f + ∫(c→b) f = ∫(a→b) f. 실수배와 합·차는 따로 적분한 것과 같다.","pre":["CA-D11"],"std":["12미적Ⅰ-03-03"]},{"id":"CA-T19","k":"T","name":"미적분의 기본정리","text":"f의 한 부정적분을 F라 하면 ∫(a→b) f(x)dx = F(b) − F(a)이고, d/dx ∫(a→x) f(t)dt = f(x)이다.","pre":["CA-D10","CA-D11"],"std":["12미적Ⅰ-03-04"],"app":"정적분 계산하기"},{"id":"CA-T20","k":"T","name":"곡선으로 둘러싸인 넓이","text":"두 곡선 y = f(x), y = g(x)와 두 직선 x = a, x = b로 둘러싸인 넓이는 ∫(a→b) (f(x) − g(x)의 절댓값) dx다.","pre":["CA-T19"],"std":["12미적Ⅰ-03-05"]},{"id":"CA-T21","k":"T","name":"속도와 거리","text":"시각 t = a에서 b까지 점의 위치의 변화량은 ∫(a→b) v(t)dt, 움직인 거리는 ∫(a→b) (v(t)의 절댓값) dt다.","pre":["CA-T19","CA-T16"],"std":["12미적Ⅰ-03-06"]}]},
  {"id":"PS","part":"고등","label":"확률과 통계","items":[{"id":"PS-D01","k":"D","name":"중복순열","text":"서로 다른 n개에서 중복을 허락하여 r개를 택해 일렬로 나열하는 순열이다. 그 수를 nΠr로 나타낸다.","pre":["C1-D06"],"std":["12확통01-01"]},{"id":"PS-T01","k":"T","name":"중복순열의 수","text":"nΠr = nʳ","pre":["PS-D01","C1-T16"],"std":["12확통01-01"]},{"id":"PS-T02","k":"T","name":"같은 것이 있는 순열의 수","text":"n개 중 같은 것이 각각 p개, q개, …, r개일 때, n개를 일렬로 나열하는 순열의 수는 n! / (p! q! … r!)이다.","pre":["C1-T17"],"std":["12확통01-01"]},{"id":"PS-D02","k":"D","name":"중복조합","text":"서로 다른 n개에서 중복을 허락하여 r개를 택하는 조합이다. 그 수를 nHr로 나타낸다.","pre":["C1-D07"],"std":["12확통01-02"]},{"id":"PS-T03","k":"T","name":"중복조합의 수","text":"nHr = (n+r−1)Cr","pre":["PS-D02","C1-T18"],"std":["12확통01-02"],"app":"방정식 x+y+z = n의 음이 아닌 정수해의 개수"},{"id":"PS-T04","k":"T","name":"이항정리","text":"(a+b)ⁿ = nC0 aⁿ + nC1 aⁿ⁻¹b + … + nCr aⁿ⁻ʳbʳ + … + nCn bⁿ","pre":["C1-T18","C1-T19"],"std":["12확통01-03"],"app":"전개식에서 특정 항의 계수 구하기"},{"id":"PS-T05","k":"T","name":"이항계수의 성질","text":"nC0 + nC1 + … + nCn = 2ⁿ이고, 파스칼의 삼각형에서 이웃한 두 수의 합은 그 아래 수와 같다.","pre":["PS-T04"],"std":["12확통01-03"]},{"id":"PS-D03","k":"D","name":"시행·표본공간·사건","text":"같은 조건에서 반복할 수 있고 결과가 우연에 의하여 결정되는 실험이 시행, 모든 결과의 집합이 표본공간 S, S의 부분집합이 사건이다.","pre":["M2-D12","C2-D03"],"std":["12확통02-01"]},{"id":"PS-D04","k":"D","name":"배반사건과 여사건","text":"A∩B = ∅인 두 사건은 서로 배반사건이다. A가 일어나지 않는 사건 Aᶜ를 A의 여사건이라 한다.","pre":["PS-D03","C2-D04"],"std":["12확통02-01"]},{"id":"PS-D05","k":"D","name":"수학적 확률","text":"표본공간의 각 근원사건이 일어날 가능성이 같을 때 P(A) = n(A) / n(S)를 사건 A의 수학적 확률이라 한다.","pre":["PS-D03","M2-D13"],"std":["12확통02-01"]},{"id":"PS-D06","k":"D","name":"통계적 확률","text":"시행을 n번 반복하여 사건 A가 r번 일어날 때, n이 커짐에 따라 상대도수 r/n이 가까워지는 일정한 값을 통계적 확률이라 한다.","pre":["PS-D03","M1-D28"],"std":["12확통02-01"]},{"id":"PS-T06","k":"T","name":"확률의 기본 성질","text":"임의의 사건 A에 대하여 0 ≤ P(A) ≤ 1, P(S) = 1, P(∅) = 0","pre":["PS-D05"],"std":["12확통02-01"]},{"id":"PS-T07","k":"T","name":"확률의 덧셈정리","text":"P(A∪B) = P(A) + P(B) − P(A∩B). A, B가 배반사건이면 P(A∪B) = P(A) + P(B)","pre":["PS-T06","C2-T13"],"std":["12확통02-02"]},{"id":"PS-T08","k":"T","name":"여사건의 확률","text":"P(Aᶜ) = 1 − P(A)","pre":["PS-T07","PS-D04"],"std":["12확통02-03"],"app":"‘적어도’가 들어간 사건의 확률"},{"id":"PS-D07","k":"D","name":"조건부확률","text":"P(A) > 0일 때, 사건 A가 일어났을 때 사건 B가 일어날 확률을 P(B∣A) = P(A∩B) / P(A)로 정한다.","pre":["PS-T06"],"std":["12확통02-04"]},{"id":"PS-T09","k":"T","name":"확률의 곱셈정리","text":"P(A∩B) = P(A) P(B∣A) = P(B) P(A∣B)","pre":["PS-D07"],"std":["12확통02-06"]},{"id":"PS-D08","k":"D","name":"독립과 종속","text":"사건 A가 일어나는 것이 사건 B가 일어날 확률에 영향을 주지 않을 때, 곧 P(B∣A) = P(B)일 때 A와 B는 서로 독립이다. 독립이 아니면 종속이다.","pre":["PS-D07"],"std":["12확통02-05"]},{"id":"PS-T10","k":"T","name":"독립의 조건","text":"두 사건 A, B가 서로 독립 ⇔ P(A∩B) = P(A) P(B)","pre":["PS-D08","PS-T09"],"std":["12확통02-05"]},{"id":"PS-T11","k":"T","name":"독립시행의 확률","text":"한 번에 사건 A가 일어날 확률이 p인 시행을 n번 독립적으로 반복할 때 A가 r번 일어날 확률은 nCr pʳ(1−p)ⁿ⁻ʳ이다.","pre":["PS-T10","C1-T18"],"std":["12확통02-05","12확통02-06"]},{"id":"PS-D09","k":"D","name":"확률변수와 확률분포","text":"표본공간의 각 원소에 실수를 하나씩 대응시킨 것이 확률변수 X다. X가 가지는 값과 그 확률의 대응 관계가 확률분포이고, 값이 셀 수 있으면 이산확률변수다.","pre":["PS-D03","C2-D08"],"std":["12확통03-01"]},{"id":"PS-D10","k":"D","name":"기댓값·분산·표준편차","text":"이산확률변수 X에 대하여 E(X) = Σxᵢpᵢ, V(X) = E((X−m)²) (m = E(X)), σ(X) = √V(X)이다.","pre":["PS-D09","M3-D12"],"std":["12확통03-02"]},{"id":"PS-T12","k":"T","name":"분산의 계산","text":"V(X) = E(X²) − {E(X)}²","pre":["PS-D10"],"std":["12확통03-02"]},{"id":"PS-T13","k":"T","name":"aX+b의 평균과 분산","text":"E(aX+b) = aE(X) + b, V(aX+b) = a²V(X), σ(aX+b) = (a의 절댓값) × σ(X)","pre":["PS-D10"],"std":["12확통03-02"]},{"id":"PS-D11","k":"D","name":"이항분포","text":"확률이 p인 독립시행을 n번 반복할 때 사건이 일어나는 횟수 X의 확률분포로, P(X = r) = nCr pʳqⁿ⁻ʳ (q = 1−p)이다. B(n, p)로 나타낸다.","pre":["PS-T11","PS-D09"],"std":["12확통03-03"]},{"id":"PS-T14","k":"T","name":"이항분포의 평균과 분산","text":"X가 B(n, p)를 따르면 E(X) = np, V(X) = npq, σ(X) = √(npq)이다.","pre":["PS-D11","PS-D10"],"std":["12확통03-03"]},{"id":"PS-D12","k":"D","name":"연속확률변수와 확률밀도함수","text":"어떤 범위의 모든 실수 값을 가지는 확률변수 X에 대하여 f(x) ≥ 0이고 그래프와 x축 사이 넓이가 1이며 P(a ≤ X ≤ b)가 그 구간의 넓이인 함수 f를 확률밀도함수라 한다.","pre":["PS-D09"],"std":["12확통03-04"]},{"id":"PS-D13","k":"D","name":"정규분포","text":"평균 m, 표준편차 σ인 종 모양의 확률밀도함수를 갖는 연속확률변수의 분포로, N(m, σ²)으로 나타낸다. N(0, 1)은 표준정규분포다.","pre":["PS-D12"],"std":["12확통03-04"]},{"id":"PS-T15","k":"T","name":"정규분포 곡선의 성질","text":"곡선은 직선 x = m에 대하여 대칭이고 x = m에서 가장 높다. σ가 클수록 낮고 넓게 퍼진다.","pre":["PS-D13"],"std":["12확통03-04"]},{"id":"PS-T16","k":"T","name":"표준화","text":"X가 N(m, σ²)을 따르면 Z = (X − m) / σ는 N(0, 1)을 따른다.","pre":["PS-D13","PS-T13"],"std":["12확통03-04"],"app":"표준정규분포표로 확률 구하기"},{"id":"PS-T17","k":"T","name":"이항분포와 정규분포","text":"X가 B(n, p)를 따르고 n이 충분히 크면 X는 근사적으로 N(np, npq)를 따른다.","pre":["PS-T14","PS-D13"],"std":["12확통03-04"]},{"id":"PS-D14","k":"D","name":"모집단과 표본","text":"조사 대상 전체가 모집단, 모집단에서 뽑은 일부가 표본이다. 모집단의 각 대상이 같은 확률로 뽑히도록 추출하는 것을 임의추출이라 한다.","pre":["M1-D26"],"std":["12확통03-05"]},{"id":"PS-D15","k":"D","name":"표본평균과 표본비율","text":"크기가 n인 표본의 평균이 표본평균 X̄, 표본에서 특정 성질을 갖는 것의 비율이 표본비율 p̂이다.","pre":["PS-D14"],"std":["12확통03-06"]},{"id":"PS-T18","k":"T","name":"표본평균의 분포","text":"모평균 m, 모표준편차 σ인 모집단에서 크기 n인 표본을 임의추출하면 E(X̄) = m, V(X̄) = σ²/n이다. 모집단이 정규분포이거나 n이 충분히 크면 X̄는 N(m, σ²/n)을 따른다.","pre":["PS-D15","PS-T16"],"std":["12확통03-06"]},{"id":"PS-T19","k":"T","name":"표본비율의 분포","text":"모비율이 p이고 n이 충분히 크면 표본비율 p̂은 근사적으로 N(p, pq/n)을 따른다.","pre":["PS-D15","PS-T17"],"std":["12확통03-06"]},{"id":"PS-D16","k":"D","name":"신뢰구간","text":"모수(모평균·모비율)가 들어 있다고 일정한 확신(신뢰도)을 갖고 말할 수 있는 범위다.","pre":["PS-T18"],"std":["12확통03-06"]},{"id":"PS-T20","k":"T","name":"모평균의 추정","text":"모집단이 정규분포 N(m, σ²)을 따르고 σ를 알 때, 크기 n인 표본의 표본평균이 x̄이면 모평균 m의 신뢰도 95% 신뢰구간은 x̄ − 1.96σ/√n ≤ m ≤ x̄ + 1.96σ/√n이다(99%는 2.58).","pre":["PS-D16","PS-T18"],"std":["12확통03-06","12확통03-07"],"app":"공학 도구로 모평균 추정하기"},{"id":"PS-T21","k":"T","name":"모비율의 추정","text":"n이 충분히 크면 모비율 p의 신뢰도 95% 신뢰구간은 p̂ − 1.96√(p̂q̂/n) ≤ p ≤ p̂ + 1.96√(p̂q̂/n)이다.","pre":["PS-D16","PS-T19"],"std":["12확통03-06","12확통03-07"],"app":"공학 도구로 모비율 추정하기"}]},
  {"id":"GE","part":"고등","label":"기하","items":[{"id":"GE-D01","k":"D","name":"포물선","text":"평면 위의 한 점 F(초점)와 F를 지나지 않는 한 직선 l(준선)에 이르는 거리가 같은 점들의 집합이다.","pre":["C2-T01","C2-T05"],"std":["12기하01-01"]},{"id":"GE-T01","k":"T","name":"포물선의 방정식","text":"초점이 F(p, 0)이고 준선이 x = −p인 포물선의 방정식은 y² = 4px, 초점이 F(0, p)이고 준선이 y = −p이면 x² = 4py이다(p ≠ 0).","pre":["GE-D01","C2-T09"],"std":["12기하01-01"],"app":"평행이동한 포물선의 꼭짓점·초점·준선 구하기"},{"id":"GE-D02","k":"D","name":"타원","text":"평면 위의 두 점 F, F'(초점)으로부터의 거리의 합이 두 초점 사이의 거리보다 큰 일정한 값인 점들의 집합이다.","pre":["C2-T01"],"std":["12기하01-02"]},{"id":"GE-T02","k":"T","name":"타원의 방정식","text":"두 초점 F(c, 0), F'(−c, 0)으로부터의 거리의 합이 2a(a > c > 0)인 타원의 방정식은 x²/a² + y²/b² = 1 (b² = a² − c²)이다. 장축의 길이는 2a, 단축의 길이는 2b다.","pre":["GE-D02","C2-T09"],"std":["12기하01-02"]},{"id":"GE-D03","k":"D","name":"쌍곡선","text":"평면 위의 두 점 F, F'(초점)으로부터의 거리의 차가 0보다 크고 두 초점 사이의 거리보다 작은 일정한 값인 점들의 집합이다.","pre":["C2-T01"],"std":["12기하01-03"]},{"id":"GE-T03","k":"T","name":"쌍곡선의 방정식","text":"두 초점 F(c, 0), F'(−c, 0)으로부터의 거리의 차가 2a(c > a > 0)인 쌍곡선의 방정식은 x²/a² − y²/b² = 1 (b² = c² − a²)이고, 점근선은 y = ±(b/a)x이다.","pre":["GE-D03","C2-T09"],"std":["12기하01-03"]},{"id":"GE-T04","k":"T","name":"이차곡선과 접선의 판별","text":"이차곡선의 방정식과 직선의 방정식을 연립하여 얻은 이차방정식의 판별식 D가 0이면, 그 직선은 이차곡선에 접한다.","pre":["GE-T01","GE-T02","GE-T03","C1-T12"],"std":["12기하01-04"],"app":"판별식으로 접선의 방정식 구하기"},{"id":"GE-T05","k":"T","name":"이차곡선의 접선의 방정식","text":"곡선 위의 점 (x₁, y₁)에서의 접선은 포물선 y² = 4px에서 y₁y = 2p(x + x₁), 타원에서 x₁x/a² + y₁y/b² = 1, 쌍곡선에서 x₁x/a² − y₁y/b² = 1이다.","pre":["GE-T04"],"std":["12기하01-04"]},{"id":"GE-D04","k":"D","name":"직선과 평면의 수직·평행","text":"직선 l이 평면 α 위의 모든 직선과 수직일 때 l과 α는 수직이다. 직선과 평면, 또는 두 평면이 만나지 않을 때 서로 평행하다. 만나는 두 평면의 공통인 직선을 교선이라 한다.","pre":["M1-D19","M1-D18"],"std":["12기하02-01"]},{"id":"GE-T06","k":"T","name":"평면이 하나로 정해지는 조건","text":"한 직선 위에 있지 않은 세 점, 한 직선과 그 위에 있지 않은 한 점, 한 점에서 만나는 두 직선, 평행한 두 직선은 각각 평면을 하나로 정한다. 서로 다른 두 평면은 평행하거나 한 직선에서 만난다.","pre":["M1-T14","GE-D04"],"std":["12기하02-01"]},{"id":"GE-T07","k":"T","name":"직선과 평면의 수직 조건","text":"직선 l이 평면 α 위의 한 점에서 만나는 두 직선과 각각 수직이면, l은 평면 α와 수직이다.","pre":["GE-D04","M2-T12"],"std":["12기하02-01"],"app":"공간도형의 위치 관계에 대한 간단한 증명"},{"id":"GE-T08","k":"T","name":"삼수선 정리","text":"평면 α 밖의 점 P, α 위의 직선 l, l 위에 있지 않은 α 위의 점 O, l 위의 점 H에 대하여 PO ⊥ α이고 OH ⊥ l이면 PH ⊥ l이다. PO ⊥ α이고 PH ⊥ l이면 OH ⊥ l이다. PH ⊥ l, OH ⊥ l, PO ⊥ OH이면 PO ⊥ α이다.","pre":["GE-T07","M2-T22"],"std":["12기하02-02"]},{"id":"GE-D05","k":"D","name":"이면각","text":"직선 l을 공유하는 두 반평면으로 이루어진 도형을 이면각이라 한다. l 위의 한 점에서 각 반평면 위에 l과 수직으로 그은 두 반직선이 이루는 각을 이면각의 크기라 한다.","pre":["GE-D04"],"std":["12기하02-03"]},{"id":"GE-D06","k":"D","name":"정사영","text":"점 P에서 평면 α에 내린 수선의 발 P'을 점 P의 평면 α 위로의 정사영이라 한다. 도형 F의 각 점의 정사영으로 이루어진 도형을 F의 정사영이라 한다.","pre":["GE-D04","M1-D18"],"std":["12기하02-03"]},{"id":"GE-T09","k":"T","name":"정사영의 길이와 넓이","text":"선분 AB와 평면 α가 이루는 각이 θ이면 정사영의 길이는 AB cos θ이다. 넓이가 S인 평면도형과 α가 이루는 각이 θ이면 정사영의 넓이는 S cos θ이다.","pre":["GE-D06","GE-D05","M3-D09"],"std":["12기하02-03"]},{"id":"GE-D07","k":"D","name":"좌표공간","text":"원점 O에서 서로 수직으로 만나는 x축, y축, z축이 정해진 공간을 좌표공간이라 하고, 점 P의 좌표를 P(a, b, c)로 나타낸다.","pre":["M1-D12"],"std":["12기하02-04"]},{"id":"GE-T10","k":"T","name":"좌표공간의 두 점 사이의 거리","text":"두 점 (x₁, y₁, z₁), (x₂, y₂, z₂) 사이의 거리는 √((x₂−x₁)² + (y₂−y₁)² + (z₂−z₁)²)이다.","pre":["GE-D07","C2-T01"],"std":["12기하02-04"]},{"id":"GE-T11","k":"T","name":"좌표공간의 내분점","text":"두 점 A(x₁, y₁, z₁), B(x₂, y₂, z₂)를 m : n으로 내분하는 점은 ((mx₂+nx₁)/(m+n), (my₂+ny₁)/(m+n), (mz₂+nz₁)/(m+n))이다.","pre":["GE-D07","C2-T02"],"std":["12기하02-04"]},{"id":"GE-D08","k":"D","name":"구","text":"공간에서 한 점(중심)으로부터 일정한 거리(반지름)에 있는 점들의 집합이다.","pre":["E6-D03","GE-D07"],"std":["12기하02-05"]},{"id":"GE-T12","k":"T","name":"구의 방정식","text":"중심이 (a, b, c)이고 반지름이 r인 구의 방정식은 (x−a)² + (y−b)² + (z−c)² = r²이다.","pre":["GE-D08","GE-T10"],"std":["12기하02-05"]},{"id":"GE-D09","k":"D","name":"벡터","text":"크기와 방향을 함께 가지는 양이다. 시점 A, 종점 B인 벡터를 벡터 AB로 나타내고, 크기가 0인 벡터를 영벡터, 크기가 1인 벡터를 단위벡터라 한다. 크기와 방향이 같은 두 벡터는 서로 같다.","pre":["M1-D16"],"std":["12기하03-01"]},{"id":"GE-D10","k":"D","name":"벡터의 덧셈·뺄셈·실수배","text":"벡터 AB + 벡터 BC = 벡터 AC로 정한다. 벡터 a − 벡터 b는 벡터 a + (−벡터 b)이다. 실수 k에 대하여 k벡터 a는 크기가 (k의 절댓값)배이고, k > 0이면 같은 방향, k < 0이면 반대 방향인 벡터다.","pre":["GE-D09"],"std":["12기하03-01"]},{"id":"GE-T13","k":"T","name":"벡터의 연산 법칙","text":"벡터의 덧셈에서 교환법칙과 결합법칙이 성립하고, 실수배에서 k(벡터 a + 벡터 b) = k벡터 a + k벡터 b, (k + l)벡터 a = k벡터 a + l벡터 a가 성립한다.","pre":["GE-D10"],"std":["12기하03-01"]},{"id":"GE-T14","k":"T","name":"벡터의 평행 조건","text":"영벡터가 아닌 두 벡터 a, b가 평행할 필요충분조건은 벡터 b = k벡터 a인 0이 아닌 실수 k가 있는 것이다.","pre":["GE-D10"],"std":["12기하03-01"],"app":"세 점이 한 직선 위에 있을 조건"},{"id":"GE-D11","k":"D","name":"위치벡터","text":"한 점 O를 시점으로 고정할 때, 벡터 OP를 점 P의 위치벡터라 한다.","pre":["GE-D09"],"std":["12기하03-02"]},{"id":"GE-T15","k":"T","name":"위치벡터의 성질","text":"두 점 A, B의 위치벡터가 a, b이면 벡터 AB = b − a이다. 선분 AB를 m : n으로 내분하는 점의 위치벡터는 (mb + na)/(m + n)이다.","pre":["GE-D11","GE-T13"],"std":["12기하03-02"]},{"id":"GE-D12","k":"D","name":"벡터의 성분","text":"좌표평면(좌표공간)에서 벡터 a를 위치벡터로 나타낼 때 종점의 좌표가 (a₁, a₂)(또는 (a₁, a₂, a₃))이면 벡터 a = (a₁, a₂)(또는 (a₁, a₂, a₃))로 나타내고, a₁, a₂, a₃을 성분이라 한다.","pre":["GE-D11","GE-D07"],"std":["12기하03-02"]},{"id":"GE-T16","k":"T","name":"성분으로 나타낸 벡터의 연산","text":"벡터 a = (a₁, a₂, a₃), 벡터 b = (b₁, b₂, b₃)이면 벡터 a ± 벡터 b = (a₁±b₁, a₂±b₂, a₃±b₃), k벡터 a = (ka₁, ka₂, ka₃)이고, 벡터 a의 크기는 √(a₁² + a₂² + a₃²)이다.","pre":["GE-D12","GE-T10"],"std":["12기하03-02"]},{"id":"GE-D13","k":"D","name":"내적","text":"영벡터가 아닌 두 벡터 a, b가 이루는 각이 θ(0 ≤ θ ≤ π)일 때, (벡터 a의 크기)(벡터 b의 크기)cos θ를 두 벡터의 내적이라 하고 벡터 a·벡터 b로 나타낸다. 벡터 a 또는 벡터 b가 영벡터이면 내적은 0으로 정한다.","pre":["GE-D09","AL-D08"],"std":["12기하03-03"]},{"id":"GE-T17","k":"T","name":"성분으로 나타낸 내적","text":"벡터 a = (a₁, a₂, a₃), 벡터 b = (b₁, b₂, b₃)이면 벡터 a·벡터 b = a₁b₁ + a₂b₂ + a₃b₃이다.","pre":["GE-D13","GE-T16","AL-T12"],"std":["12기하03-03"]},{"id":"GE-T18","k":"T","name":"내적과 각·수직","text":"벡터 a·벡터 a = (벡터 a의 크기)²이다. 두 벡터가 이루는 각 θ에 대하여 cos θ = (벡터 a·벡터 b) ÷ {(벡터 a의 크기)(벡터 b의 크기)}이고, 영벡터가 아닌 두 벡터에서 벡터 a ⊥ 벡터 b ⇔ 벡터 a·벡터 b = 0이다.","pre":["GE-D13","GE-T17"],"std":["12기하03-03"]},{"id":"GE-D14","k":"D","name":"방향벡터와 법선벡터","text":"직선에 평행한 영벡터가 아닌 벡터를 그 직선의 방향벡터, 평면에 수직인 영벡터가 아닌 벡터를 그 평면의 법선벡터라 한다.","pre":["GE-D09","GE-D04"],"std":["12기하03-04"]},{"id":"GE-T19","k":"T","name":"벡터로 나타낸 직선의 방정식","text":"점 A(x₁, y₁, z₁)를 지나고 방향벡터가 (a, b, c)인 직선의 방정식은 (x−x₁)/a = (y−y₁)/b = (z−z₁)/c (abc ≠ 0)이다. 좌표평면에서는 (x−x₁)/a = (y−y₁)/b (ab ≠ 0)이다.","pre":["GE-D14","GE-T15"],"std":["12기하03-04"],"app":"두 점을 지나는 직선의 방정식, 두 직선이 이루는 각"},{"id":"GE-T20","k":"T","name":"평면의 방정식","text":"점 A(x₁, y₁, z₁)를 지나고 법선벡터가 (a, b, c)인 평면의 방정식은 a(x−x₁) + b(y−y₁) + c(z−z₁) = 0이다.","pre":["GE-D14","GE-T18"],"std":["12기하03-05"]},{"id":"GE-T21","k":"T","name":"벡터로 나타낸 구의 방정식","text":"중심 C의 위치벡터를 c, 반지름을 r이라 하면 구 위의 점 P의 위치벡터 p는 (p − c)·(p − c) = r²을 만족한다. 이를 성분으로 쓰면 구의 방정식이 된다.","pre":["GE-T18","GE-T12"],"std":["12기하03-05"]}]}
];
